// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests
// IMPROVED VERSION with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation errors for security monitoring
    console.error('Validation error:', {
      path: req.path,
      errors: errors.array(),
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
    return res.status(400).json({
      error: 'Invalid input',
      message: 'The request contains invalid data'
    });
  }
  next();
};

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests',
    message: 'Please try again later'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limit for user endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20, // 20 requests per 15 minutes for user data
  message: {
    error: 'Too many requests',
    message: 'User endpoint rate limit exceeded'
  }
});

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Apply rate limiting
app.use(limiter);

// Request size limit to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request logging middleware for security monitoring
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    // Log requests (in production, use proper logging library)
    console.log({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
});

// Sanitize query parameters helper
function sanitizeQueryParams(req) {
  const sanitized = {};
  for (const key in req.query) {
    // Remove any null bytes and trim whitespace
    const value = req.query[key]
      .replace(/\0/g, '')
      .trim()
      .substring(0, 100); // Limit length
    sanitized[key] = value;
  }
  return sanitized;
}

// Health endpoint with validation
app.get('/health', [
  query('format').optional().isIn(['json', 'text']).withMessage('Invalid format'),
  validateRequest
], (req, res) => {
  try {
    const sanitized = sanitizeQueryParams(req);
    const responseData = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (sanitized.format === 'text') {
      res.set('Content-Type', 'text/plain');
      return res.send(`Status: ${responseData.status}\nTimestamp: ${responseData.timestamp}`);
    }

    res.json(responseData);
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint with validation and stricter rate limiting
app.get('/users', [
  userLimiter,
  query('id').optional().isInt({ min: 1, max: 1000 }).withMessage('Invalid user ID'),
  query('fields').optional()
    .matches(/^[a-zA-Z,]+$/)
    .withMessage('Fields parameter contains invalid characters'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Invalid limit'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Invalid offset'),
  validateRequest
], (req, res) => {
  try {
    const sanitized = sanitizeQueryParams(req);

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    let result = users;
    if (sanitized.id) {
      result = users.filter(user => user.id === parseInt(sanitized.id, 10));
      if (result.length === 0) {
        return res.status(404).json({
          error: 'Not found',
          message: 'User not found'
        });
      }
    }

    // Handle fields filtering safely
    if (sanitized.fields) {
      const allowedFields = ['id', 'name', 'email'];
      const requestedFields = sanitized.fields.split(',').map(f => f.trim());
      const validFields = requestedFields.filter(f => allowedFields.includes(f));

      if (validFields.length > 0) {
        result = result.map(user => {
          const filtered = {};
          validFields.forEach(field => {
            if (user[field] !== undefined) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }
    }

    // Handle pagination safely
    let paginatedResult = result;
    if (sanitized.limit || sanitized.offset) {
      const offset = parseInt(sanitized.offset || '0', 10);
      const limit = parseInt(sanitized.limit || '100', 10);

      // Validate offset doesn't exceed array length
      if (offset >= result.length) {
        return res.status(400).json({
          error: 'Invalid offset',
          message: 'Offset exceeds available results'
        });
      }

      paginatedResult = result.slice(offset, offset + limit);
    }

    res.json({
      data: paginatedResult,
      meta: {
        count: paginatedResult.length,
        total: result.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', {
      error: error.message,
      stack: error.stack,
      path: req.path,
      ip: req.ip
    });
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// Global error handling middleware (must be last)
app.use((err, req, res, next) => {
  // Log error details for debugging (in production, use proper logging)
  console.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Only start server if not being imported for testing
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

