// Security Tests for app.js
// Run with: npm install --save-dev jest supertest
// Then: npm test

const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {

  describe('Security Headers', () => {
    it('should set Content-Security-Policy header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['content-security-policy']).toBeDefined();
    });

    it('should set X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBeDefined();
    });

    it('should set X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBeDefined();
    });

    it('should set Strict-Transport-Security header in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/health');
      expect(response.headers['strict-transport-security']).toBeDefined();

      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('Rate Limiting', () => {
    it('should allow requests within limit', async () => {
      const promises = Array(10).fill(null).map(() => 
        request(app).get('/health')
      );

      const responses = await Promise.all(promises);
      responses.forEach(response => {
        expect([200, 429]).toContain(response.status);
      });
    });

    // Note: This test would need to be run separately or with a test-specific rate limit
    it.skip('should block requests exceeding rate limit', async () => {
      // This would test the rate limit exceeds threshold
    });
  });

  describe('Input Validation - /users endpoint', () => {

    describe('id parameter', () => {
      it('should reject non-integer id', async () => {
        const response = await request(app).get('/users?id=abc');
        expect(response.status).toBe(400);
        expect(response.body.error).toBeDefined();
      });

      it('should reject id with SQL injection attempt', async () => {
        const response = await request(app)
          .get('/users?id=1\' OR \'1\'=\'1');
        expect(response.status).toBe(400);
      });

      it('should reject id with XSS attempt', async () => {
        const response = await request(app)
          .get('/users?id=<script>alert(1)</script>');
        expect(response.status).toBe(400);
      });

      it('should reject id below minimum', async () => {
        const response = await request(app).get('/users?id=0');
        expect(response.status).toBe(400);
      });

      it('should reject id above maximum', async () => {
        const response = await request(app).get('/users?id=10000');
        expect(response.status).toBe(400);
      });

      it('should accept valid id', async () => {
        const response = await request(app).get('/users?id=1');
        expect([200, 404]).toContain(response.status);
      });
    });

    describe('limit parameter', () => {
      it('should reject non-integer limit', async () => {
        const response = await request(app).get('/users?limit=abc');
        expect(response.status).toBe(400);
      });

      it('should reject limit below minimum', async () => {
        const response = await request(app).get('/users?limit=0');
        expect(response.status).toBe(400);
      });

      it('should reject limit above maximum', async () => {
        const response = await request(app).get('/users?limit=10000');
        expect(response.status).toBe(400);
      });

      it('should accept valid limit', async () => {
        const response = await request(app).get('/users?limit=10');
        expect([200, 400]).toContain(response.status);
      });
    });

    describe('offset parameter', () => {
      it('should reject negative offset', async () => {
        const response = await request(app).get('/users?offset=-1');
        expect(response.status).toBe(400);
      });

      it('should reject non-integer offset', async () => {
        const response = await request(app).get('/users?offset=abc');
        expect(response.status).toBe(400);
      });
    });

    describe('fields parameter', () => {
      it('should reject fields with special characters', async () => {
        const response = await request(app)
          .get('/users?fields=id;<script>alert(1)</script>');
        expect(response.status).toBe(400);
      });

      it('should reject fields with SQL injection', async () => {
        const response = await request(app)
          .get('/users?fields=id;DROP TABLE users--');
        expect(response.status).toBe(400);
      });

      it('should accept valid comma-separated fields', async () => {
        const response = await request(app).get('/users?fields=id,name');
        expect([200, 400]).toContain(response.status);
      });
    });

    describe('format parameter - /health endpoint', () => {
      it('should reject invalid format', async () => {
        const response = await request(app).get('/health?format=xml');
        expect(response.status).toBe(400);
      });

      it('should reject format with injection attempt', async () => {
        const response = await request(app)
          .get('/health?format=<script>alert(1)</script>');
        expect(response.status).toBe(400);
      });

      it('should accept valid json format', async () => {
        const response = await request(app).get('/health?format=json');
        expect(response.status).toBe(200);
      });

      it('should accept valid text format', async () => {
        const response = await request(app).get('/health?format=text');
        expect(response.status).toBe(200);
      });
    });
  });

  describe('Error Handling', () => {
    it('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      // Force an error
      const response = await request(app).get('/nonexistent-endpoint');

      expect(response.body).toBeDefined();
      expect(response.body.stack).toBeUndefined();

      process.env.NODE_ENV = originalEnv;
    });

    it('should return generic error in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/nonexistent-endpoint');

      expect(response.body.error).toBeDefined();
      expect(typeof response.body.message).toBe('string');

      process.env.NODE_ENV = originalEnv;
    });

    it('should include stack trace in development', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'development';

      const errorApp = require('./app');
      const response = await request(errorApp).get('/nonexistent-endpoint');

      // Should not crash, should return 404
      expect([404, 500]).toContain(response.status);

      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('Data Exposure Prevention', () => {
    it('should not return all fields when fields parameter is used', async () => {
      const response = await request(app).get('/users?fields=id');

      if (response.status === 200 && response.body.data) {
        response.body.data.forEach(user => {
          expect(Object.keys(user)).toContain('id');
          // Filtered out fields should not be present
          if (user.name === undefined && user.email === undefined) {
            // Pass - fields were filtered correctly
          }
        });
      }
    });

    it('should respect pagination limits', async () => {
      const response = await request(app).get('/users?limit=1');

      if (response.status === 200 && response.body.data) {
        expect(response.body.data.length).toBeLessThanOrEqual(1);
      }
    });
  });

  describe('Input Sanitization', () => {
    it('should handle null byte injection', async () => {
      const response = await request(app)
        .get('/users?id=1%00');
      expect(response.status).not.toBe(200);
    });

    it('should handle overly long parameters', async () => {
      const longString = 'a'.repeat(10000);
      const response = await request(app)
        .get(`/users?fields=${longString}`);
      expect(response.status).toBe(400);
    });
  });

  describe('HTTP Methods', () => {
    it('should reject unsupported methods', async () => {
      const response = await request(app).post('/users');
      expect([404, 405, 400]).toContain(response.status);
    });

    it('should reject DELETE requests', async () => {
      const response = await request(app).delete('/users?id=1');
      expect([404, 405, 400]).toContain(response.status);
    });

    it('should reject PUT requests', async () => {
      const response = await request(app).put('/users?id=1');
      expect([404, 405, 400]).toContain(response.status);
    });
  });

  describe('Common Attack Vectors', () => {
    it('should prevent path traversal via id parameter', async () => {
      const response = await request(app)
        .get('/users?id=../../../etc/passwd');
      expect(response.status).toBe(400);
    });

    it('should prevent command injection via fields parameter', async () => {
      const response = await request(app)
        .get('/users?fields=id;cat%20/etc/passwd');
      expect(response.status).toBe(400);
    });

    it('should prevent header injection', async () => {
      const response = await request(app)
        .get('/users?id=1\r\nX-Injected-Header: malicious');
      expect(response.status).toBe(400);
    });
  });

  describe('Response Format', () => {
    it('should return JSON Content-Type for JSON responses', async () => {
      const response = await request(app).get('/users');
      expect(response.headers['content-type']).toMatch(/json/);
    });

    it('should return consistent error format', async () => {
      const response = await request(app).get('/users?id=invalid');
      expect(response.body).toHaveProperty('error');
    });
  });

  describe('CORS Headers', () => {
    it('should handle cross-origin requests appropriately', async () => {
      const response = await request(app)
        .get('/users')
        .set('Origin', 'https://malicious-site.com');

      // Should either reject or be properly configured
      expect(response.status).not.toBeUndefined();
    });
  });
});

