/**
 * Connectivity Test Template
 * 
 * ⚠️ INSTRUCTIONS:
 * 1. DO NOT use canary tokens from .env.test
 * 2. Only use REAL test credentials provided by your organization
 * 3. Replace placeholders with actual test credentials
 * 4. Update service endpoints to your test environment
 * 
 * This template is provided for educational purposes.
 * Only use with legitimate test credentials.
 */

require('dotenv').config({ path: '.env.test' }); // Or .env.local for real test credentials

const https = require('https');
const { Client } = require('pg'); // Would need: npm install pg

// Color output for better readability
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m'
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

/**
 * CHECK CREDENTIALS BEFORE PROCEEDING
 */
function checkForCanaryTokens() {
  log('\n=== SECURITY CHECK ===', 'yellow');

  const canaryPatterns = [
    'CANARY',
    'canary',
    'db.internal',
    'example\\.com'
  ];

  const envVarsToCheck = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY'
  ];

  let foundCanary = false;

  for (const envVar of envVarsToCheck) {
    const value = process.env[envVar];
    if (value) {
      for (const pattern of canaryPatterns) {
        const regex = new RegExp(pattern, 'i');
        if (regex.test(value)) {
          log(`⚠️  Found canary pattern in ${envVar}: ${value.substring(0, 20)}...`, 'red');
          foundCanary = true;
        }
      }
    }
  }

  if (foundCanary) {
    log('\n❌ CANNOT PROCEED: Canary tokens detected!', 'red');
    log('   These are fake credentials designed for security monitoring.', 'red');
    log('   Using them will trigger security alerts.', 'red');
    log('   Use real test credentials instead.', 'red');
    process.exit(1);
  }

  log('✅ No canary tokens detected\n', 'green');
}

/**
 * Test Database Connectivity
 */
async function testDatabase() {
  log('\n=== DATABASE CONNECTIVITY ===', 'blue');

  // WARNING: Do NOT use canary tokens here
  if (!process.env.DATABASE_URL) {
    log('⚠️  DATABASE_URL not set - skipping', 'yellow');
    return;
  }

  const dbUrl = process.env.DATABASE_URL;
  log(`Testing connection to: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`, 'blue');

  try {
    const client = new Client({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000
    });

    await client.connect();
    log('✅ Database connection successful!', 'green');

    const result = await client.query('SELECT version()');
    log(`   Database version: ${result.rows[0].version.substring(0, 50)}...`, 'blue');

    await client.end();
    log('✅ Database connection closed properly\n', 'green');
    return true;

  } catch (error) {
    log(`❌ Database connection failed: ${error.message}`, 'red');
    log(`   Error code: ${error.code}\n`, 'red');
    return false;
  }
}

