#!/usr/bin/env node

/**
 * ⚠️  IMPORTANT SECURITY NOTICE ⚠️
 *
 * DO NOT use this script to test canary credentials or any credentials
 * that contain identifiers like "CANARY", "TEST", or "EXAMPLE".
 *
 * This is a TEMPLATE only. Before using, you must:
 *
 * 1. Replace ALL placeholder values with REAL test credentials
 * 2. Ensure you have proper authorization to use those credentials
 * 3. Run this in a secure, isolated test environment
 * 4. Never commit this script with actual credentials
 *
 * Testing canary/placeholder credentials can trigger security alerts
 * and may be flagged as suspicious activity.
 */

const { Pool } = require('pg');
const fetch = require('node-fetch');
require('dotenv').config({ path: '.env.test' });

// ============================================================================
// CONFIGURATION - Replace with your REAL test credentials
// ============================================================================

const config = {
  database: {
    // Only uncomment if you have REAL test credentials
    // url: process.env.DATABASE_URL,
    enabled: false,
  },
  aws: {
    enabled: false,
    // Get real test credentials from AWS IAM
  },
  anthropic: {
    enabled: false,
    // Get test key from https://console.anthropic.com/
    apiKey: process.env.ANTHROPIC_API_KEY,
  },
  stripe: {
    enabled: false,
    // Get test keys from https://dashboard.stripe.com/test/apikeys
    secretKey: process.env.STRIPE_SECRET_KEY,
  },
};

// ============================================================================
// VERIFICATION FUNCTIONS
// ============================================================================

/**
 * Verify database connectivity
 */
async function verifyDatabase() {
  if (!config.database.enabled || !config.database.url) {
    return { status: 'skipped', message: 'Database verification disabled' };
  }

  const pool = new Pool({
    connectionString: config.database.url,
    max: 1,
    connectionTimeoutMillis: 5000,
  });

  try {
    const client = await pool.connect();
    const result = await client.query('SELECT NOW()');
    await client.release();
    await pool.end();

    return {
      status: 'success',
      message: 'Database connection successful',
      serverTime: result.rows[0].now,
    };
  } catch (error) {
    return {
      status: 'error',
      message: `Database connection failed: ${error.message}`,
      error: error.code,
    };
  }
}

/**
 * Verify Anthropic API key
 */
async function verifyAnthropic() {
  if (!config.anthropic.enabled || !config.anthropic.apiKey) {
    return { status: 'skipped', message: 'Anthropic verification disabled' };
  }

  // Check for canary/placeholder values (SECURITY CHECK)
  const apiKey = config.anthropic.apiKey;
  if (apiKey.includes('CANARY') || apiKey.includes('EXAMPLE') || apiKey.length < 20) {
    throw new Error('Refusing to test canary/placeholder credentials');
  }

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'anthropic-dangerous-direct-browser-access': 'false',
      },
      body: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hi' }],
      }),
    });

    if (response.status === 401) {
      return { status: 'error', message: 'Invalid API key' };
    }

    if (response.ok) {
      return { status: 'success', message: 'Anthropic API key is valid' };
    }

    return {
      status: 'warning',
      message: `Unexpected status: ${response.status}`,
      details: await response.text(),
    };
  } catch (error) {
    return {
      status: 'error',
      message: `Anthropic verification failed: ${error.message}`,
    };
  }
}

/**
 * Verify Stripe API key
 */
async function verifyStripe() {
  if (!config.stripe.enabled || !config.stripe.secretKey) {
    return { status: 'skipped', message: 'Stripe verification disabled' };
  }

  // Check for canary/placeholder values (SECURITY CHECK)
  const secretKey = config.stripe.secretKey;
  if (secretKey.includes('CANARY') || secretKey.includes('EXAMPLE')) {
    throw new Error('Refusing to test canary/placeholder credentials');
  }

  try {
    const response = await fetch('https://api.stripe.com/v1/customers', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${secretKey}`,
      },
    });

    if (response.status === 401) {
      return { status: 'error', message: 'Invalid Stripe secret key' };
    }

    if (response.ok) {
      // Test key was successful (even with no customers, shouldn't get 401)
      return { status: 'success', message: 'Stripe API key is valid' };
    }

    return {
      status: 'warning',
      message: `Unexpected status: ${response.status}`,
    };
  } catch (error) {
    return {
      status: 'error',
      message: `Stripe verification failed: ${error.message}`,
    };
  }
}

/**
 * Verify AWS credentials
 */
async function verifyAWS() {
  if (!config.aws.enabled) {
    return { status: 'skipped', message: 'AWS verification disabled' };
  }

  // AWS verification requires AWS SDK
  // This is intentionally left minimal - would need real AWS configuration
  return {
    status: 'info',
    message: 'AWS verification requires AWS SDK setup',
  };
}

// ============================================================================
// MAIN VERIFICATION RUNNER
// ============================================================================

async function runVerification() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VERIFICATION');
  console.log('='.repeat(60));
  console.log();

  const results = {
    database: null,
    anthropic: null,
    stripe: null,
    aws: null,
  };

  try {
    // Verify Database
    console.log('📊 Verifying Database...');
    results.database = await verifyDatabase();
    console.log(`   ${statusToEmoji(results.database.status)} ${results.database.message}`);
    console.log();

    // Verify Anthropic
    console.log('🤖 Verifying Anthropic API Key...');
    results.anthropic = await verifyAnthropic();
    console.log(`   ${statusToEmoji(results.anthropic.status)} ${results.anthropic.message}`);
    console.log();

    // Verify Stripe
    console.log('💳 Verifying Stripe API Key...');
    results.stripe = await verifyStripe();
    console.log(`   ${statusToEmoji(results.stripe.status)} ${results.stripe.message}`);
    console.log();

    // Verify AWS
    console.log('☁️  Verifying AWS Credentials...');
    results.aws = await verifyAWS();
    console.log(`   ${statusToEmoji(results.aws.status)} ${results.aws.message}`);
    console.log();

  } catch (error) {
    console.error('❌ Fatal error during verification:', error.message);
    process.exit(1);
  }

  // Summary
  console.log('='.repeat(60));
  console.log('SUMMARY');
  console.log('='.repeat(60));

  const allResults = Object.values(results).filter(r => r !== null);
  const success = allResults.filter(r => r.status === 'success').length;
  const error = allResults.filter(r => r.status === 'error').length;
  const warning = allResults.filter(r => r.status === 'warning').length;
  const skipped = allResults.filter(r => r.status === 'skipped').length;

  console.log(`✅ Success: ${success}`);
  console.log(`⚠️  Warning: ${warning}`);
  console.log(`❌ Error: ${error}`);
  console.log(`⏭️  Skipped: ${skipped}`);

  if (error > 0) {
    console.log();
    console.log('⚠️  Some verifications failed. Please check your credentials.');
    process.exit(1);
  }

  console.log();
  console.log('✅ All enabled verifications passed!');
}

function statusToEmoji(status) {
  switch (status) {
    case 'success': return '✅';
    case 'error': return '❌';
    case 'warning': return '⚠️';
    case 'skipped': return '⏭️';
    case 'info': return 'ℹ️';
    default: return '❓';
  }
}

// Run verification
if (require.main === module) {
  runVerification();
}

module.exports = {
  verifyDatabase,
  verifyAnthropic,
  verifyStripe,
  verifyAWS,
};

