const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // More restrictive for sensitive operations
  message: 'Too many attempts, please try again later.',
});

// Body parsing with size limits and security options
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  strict: true,  // Only accept objects and arrays
}));

app.use(express.urlencoded({
  extended: false,
  limit: '10kb',
}));

// Request logging middleware (security-focused)
app.use((req, res, next) => {
  // Log suspicious patterns
  const suspiciousPatterns = [
    /<script/i,
    /javascript:/i,
    /on\w+\s*=/i,
    /\.\./,
  ];

  const queryString = JSON.stringify(req.query);
  const hasSuspiciousInput = suspiciousPatterns.some(pattern => 
    pattern.test(queryString) || pattern.test(req.path)
  );

  if (hasSuspiciousInput) {
    console.warn(`[SECURITY] Suspicious request from ${req.ip}: ${req.method} ${req.path}`);
  }

  next();
});

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`[VALIDATION] Request validation failed: ${JSON.stringify(errors.array())}`);
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitization helper functions
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    // Remove potentially dangerous characters
    return data
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;')
      .replace(/\//g, '&#x2F;');
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeOutput);
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[sanitizeOutput(key)] = sanitizeOutput(value);
    }
    return sanitized;
  }
  return data;
};

// Security headers middleware
app.use((req, res, next) => {
  // Remove server header to prevent information disclosure
  res.removeHeader('X-Powered-By');
  // Add custom security header
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});

// Health endpoint with validation
app.get('/health', 
  [
    query('format').optional().isIn(['json', 'text']).withMessage('Invalid format')
  ],
  validateRequest,
  (req, res) => {
    try {
      const { format = 'json' } = req.query;

      if (format === 'text') {
        res.set('Content-Type', 'text/plain');
        return res.send('OK');
      }

      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    } catch (error) {
      console.error(`[ERROR] Health endpoint error: ${error.message}`);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Users endpoint with pagination and filtering
app.get('/users',
  [
    query('page').optional().isInt({ min: 1, max: 100 }).withMessage('Page must be between 1 and 100'),
    query('limit').optional().isInt({ min: 1, max: 50 }).withMessage('Limit must be between 1 and 50'),
    query('sort').optional().matches(/^(name|email|id)(:(asc|desc))?$/).withMessage('Invalid sort parameter'),
    query('search').optional().isLength({ max: 100 }).trim().escape().withMessage('Search term too long'),
  ],
  validateRequest,
  sensitiveLimiter,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters with safe defaults
      let filteredUsers = [...users];

      // Search filter with SQL injection prevention
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(searchTerm) ||
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Sorting with whitelist
      if (req.query.sort) {
        const [field, order] = req.query.sort.split(':');
        const sortField = field || 'id';
        const sortOrder = order === 'desc' ? -1 : 1;

        if (['name', 'email', 'id'].includes(sortField)) {
          filteredUsers.sort((a, b) => {
            if (a[sortField] < b[sortField]) return -1 * sortOrder;
            if (a[sortField] > b[sortField]) return 1 * sortOrder;
            return 0;
          });
        }
      }

      // Pagination
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;

      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Sanitize output
      const sanitizedUsers = sanitizeOutput(paginatedUsers);

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit)
        }
      });
    } catch (error) {
      console.error(`[ERROR] Users endpoint error: ${error.message}`);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for monitoring (not exposing sensitive info)
  console.error(`[ERROR] ${err.name}: ${err.message}`, {
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(isDevelopment && { 
      message: err.message,
      stack: err.stack 
    })
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('[FATAL] Uncaught Exception:', error);
  // Graceful shutdown in production
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('[FATAL] Unhandled Rejection at:', promise, 'reason:', reason);
  // Graceful shutdown in production
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

