// Improved application with security best practices
// This includes error handling, input validation, and security hardening

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security-related HTTP headers
app.use(helmet());

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: Math.round(req.rateLimit.resetTime / 1000)
    });
  }
});

// Stricter rate limiting for API endpoints
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 50,
  message: { error: 'Too many API requests' }
});

app.use(limiter);

// Body size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Middleware to check validation results
 * Returns 400 with detailed error information if validation fails
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

/**
 * Sanitize and validate query parameters
 */
const sanitizeQueryParams = (req, res, next) => {
  // Remove any potentially dangerous characters from query params
  for (const key in req.query) {
    if (typeof req.query[key] === 'string') {
      // Remove potential XSS vectors
      req.query[key] = req.query[key]
        .replace(/[<>]/g, '')
        .trim();
    }
  }
  next();
};

app.use(sanitizeQueryParams);

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Global error handler - catches all errors
 * Never exposes stack traces in production
 */
const errorHandler = (err, req, res, next) => {
  // Log error for monitoring (in production, use proper logging service)
  console.error(`[ERROR] ${new Date().toISOString()}:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak sensitive error details to clients
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
};

/**
 * 404 handler for undefined routes
 */
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
};

/**
 * Async handler wrapper to catch errors in async route handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// ROUTES WITH VALIDATION AND ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 * Returns limited information to avoid exposing system details
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok',
      // Use UTC timestamp to avoid timezone info leakage
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users endpoint with validation
 * Supports optional filtering with sanitized input
 */
app.get('/users', 
  // Validate query parameters
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer')
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const { limit, offset, id } = req.query;

    let filteredUsers = users;

    // Filter by ID if provided
    if (id) {
      filteredUsers = users.filter(user => user.id === parseInt(id));
    }

    // Apply pagination
    const startIndex = offset ? parseInt(offset) : 0;
    const endIndex = limit ? startIndex + parseInt(limit) : filteredUsers.length;

    // Validate array bounds to prevent negative slicing issues
    if (startIndex < 0 || startIndex > filteredUsers.length) {
      return res.status(400).json({
        error: 'Invalid offset',
        message: 'Offset exceeds available data'
      });
    }

    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        offset: startIndex,
        limit: limit || filteredUsers.length
      }
    });
  })
);

/**
 * Example POST endpoint with input validation
 * Demonstrates body validation and sanitization
 */
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address')
      .isLength({ max: 255 })
      .withMessage('Email too long')
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // In a real application, save to database here
    const newUser = {
      id: Date.now(), // Note: Use proper ID generation in production
      name,
      email
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  })
);

// ============================================
// ERROR HANDLERS (Must be last)
// ============================================

// 404 handler - must be after all routes
app.use(notFoundHandler);

// Global error handler - must be last
app.use(errorHandler);

// ============================================
// SERVER STARTUP WITH ERROR HANDLING
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  shutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('unhandledRejection');
});

module.exports = app;

