const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ===========================================
// SECURITY MIDDLEWARE
// ===========================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xframeOptions: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  handler: (req, res) => {
    // Log rate limit violations
    console.warn(`Rate limit exceeded for IP: ${req.ip} at ${new Date().toISOString()}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.'
    });
  }
});

app.use('/api', limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  skipSuccessfulRequests: true,
  message: { error: 'Too many attempts' }
});

// Body size limits to prevent payload attacks
app.use(express.json({ 
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({ 
  limit: '10kb', 
  extended: false,
  parameterLimit: 100 
}));

// ===========================================
// VALIDATION MIDDLEWARE
// ===========================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures (without sensitive data)
    console.warn(`Validation failed for ${req.method} ${req.path}: ${errors.array().length} errors`);
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitization helpers
const sanitizeNumber = (value, min = 0, max = Number.MAX_SAFE_INTEGER) => {
  const num = parseInt(value, 10);
  if (isNaN(num)) throw new Error('Invalid number');
  if (num < min || num > max) throw new Error('Number out of range');
  return num;
};

const sanitizeString = (value, maxLength = 100) => {
  if (typeof value !== 'string') throw new Error('Invalid string');
  const trimmed = value.trim();
  if (trimmed.length === 0) throw new Error('Empty string');
  if (trimmed.length > maxLength) throw new Error('String too long');
  // Remove potential XSS characters
  return trimmed.replace(/[<>]/g, '');
};

const sanitizeEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) throw new Error('Invalid email format');
  return email.toLowerCase().trim();
};

// ===========================================
// REQUEST LOGGER (Security Audit Trail)
// ===========================================

app.use((req, res, next) => {
  const startTime = Date.now();

  // Log request details (without sensitive data)
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent')
  }));

  // Capture response status for logging
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip
    }));
  });

  next();
});

// ===========================================
// ERROR HANDLING MIDDLEWARE
// ===========================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error details
  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    error: {
      name: err.name,
      message: err.message,
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
    },
    request: {
      method: req.method,
      path: req.path,
      ip: req.ip
    }
  }));

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send appropriate error response
  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An unexpected error occurred',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===========================================
// CUSTOM ERROR CLASSES
// ===========================================

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

class AuthenticationError extends Error {
  constructor(message = 'Authentication failed') {
    super(message);
    this.name = 'AuthenticationError';
    this.statusCode = 401;
  }
}

class AuthorizationError extends Error {
  constructor(message = 'Access denied') {
    super(message);
    this.name = 'AuthorizationError';
    this.statusCode = 403;
  }
}

class NotFoundError extends Error {
  constructor(message = 'Resource not found') {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

class RateLimitError extends Error {
  constructor(message = 'Rate limit exceeded') {
    super(message);
    this.name = 'RateLimitError';
    this.statusCode = 429;
  }
}

// ===========================================
// ROUTES WITH VALIDATION
// ===========================================

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    next(err);
  }
});

// Get users with pagination, filtering, and sorting
app.get('/users', [
  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Sort must be one of: id, name, email'),
  query('order')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Order must be either asc or desc'),
  query('search')
    .optional()
    .isLength({ max: 50 })
    .withMessage('Search term too long')
    .trim()
    .escape()
], handleValidationErrors, (req, res, next) => {
  try {
    // Get validated query parameters with defaults
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const sort = req.query.sort || 'id';
    const order = req.query.order || 'asc';
    const search = req.query.search || '';

    // Mock user data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply search filter
    let filteredUsers = allUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = allUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply sorting
    filteredUsers.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      if (aVal < bVal) return order === 'asc' ? -1 : 1;
      if (aVal > bVal) return order === 'asc' ? 1 : -1;
      return 0;
    });

    // Apply pagination
    const start = (page - 1) * limit;
    const paginatedUsers = filteredUsers.slice(start, start + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      },
      filters: { search, sort, order }
    });
  } catch (err) {
    next(err);
  }
});

// Get single user by ID
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
], handleValidationErrors, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // Mock user lookup (in production, fetch from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new NotFoundError(`User with ID ${userId} not found`);
    }

    res.json({ data: user });
  } catch (err) {
    next(err);
  }
});

// Create new user with validation
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address')
    .isLength({ max: 255 })
    .withMessage('Email too long'),
], handleValidationErrors, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // In production, save to database with parameterized queries
    const newUser = {
      id: Date.now(), // Simple ID generation (use proper system in production)
      name: sanitizeString(name),
      email: sanitizeEmail(email)
    };

    // Log user creation (without sensitive data)
    console.log(`User created: ID ${newUser.id}`);

    res.status(201).json({ 
      message: 'User created successfully',
      data: { id: newUser.id, name: newUser.name } 
    });
  } catch (err) {
    next(err);
  }
});

// ===========================================
// SERVER STARTUP
// ===========================================

const PORT = process.env.PORT || 3000;

// Only listen if not being imported (for testing)
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));
}

module.exports = { app, ValidationError, AuthenticationError, AuthorizationError, NotFoundError };

