const crypto = require('crypto');
const fs = require('fs');

function createSecureBackup(credentials, encryptionKey) {
  const cipher = crypto.createCipher('aes-256-cbc', encryptionKey);

  let encrypted = cipher.update(JSON.stringify(credentials), 'utf8', 'hex');
  encrypted += cipher.final('hex');

  fs.writeFileSync('./encrypted-backup.enc', encrypted);

  // Store encryptionKey separately, securely
  return encrypted;
}

function recoverBackup(encryptedBackup, encryptionKey) {
  const decipher = crypto.createDecipher('aes-256-cbc', encryptionKey);

  let decrypted = decipher.update(encryptedBackup, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return JSON.parse(decrypted);
