  `SELECT * FROM users WHERE id = '${userId}'`
);
```

### 6. Password Security (When Authentication Added)
```javascript
const bcrypt = require('bcrypt');
const SALT_ROUNDS = 12;

// Hash passwords
const hashedPassword = await bcrypt.hash(plainPassword, SALT_ROUNDS);

// Compare passwords
const isValid = await bcrypt.compare(plainPassword, hashedPassword);
```

### 7. JWT Security (When Using Tokens)
```javascript
const jwt = require('jsonwebtoken');

// Use strong secrets from environment
const JWT_SECRET = process.env.JWT_SECRET; // Must be 32+ characters
const JWT_EXPIRY = '15m'; // Short expiry for access tokens

// Validate tokens
jwt.verify(token, JWT_SECRET, { algorithms: ['HS256'] }, (err, decoded) => {
  if (err) throw new Error('Invalid token');
});
