#!/usr/bin/env node

/**
 * Environment Variable Configuration Check
 * Run this script to verify environment variables are properly loaded
 */

const fs = require('fs');
const path = require('path');

// ANSI colors for terminal output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

console.log('\n' + colors.cyan + '═'.repeat(60) + colors.reset);
console.log(colors.cyan + '  ENVIRONMENT VARIABLE CONFIGURATION CHECK' + colors.reset);
console.log(colors.cyan + '═'.repeat(60) + colors.reset + '\n');

// Define expected variables with metadata
const expectedVars = {
  NODE_ENV: { required: false, default: 'development', description: 'Application environment' },
  PORT: { required: false, default: '3000', description: 'Server port' },
  DATABASE_URL: { required: false, default: null, description: 'Database connection string' },
  AWS_ACCESS_KEY_ID: { required: false, default: null, description: 'AWS access key' },
  AWS_SECRET_ACCESS_KEY: { required: false, default: null, description: 'AWS secret key' },
  ANTHROPIC_API_KEY: { required: false, default: null, description: 'Anthropic API key' },
  STRIPE_SECRET_KEY: { required: false, default: null, description: 'Stripe secret key' },
  LOGFIRE_TOKEN: { required: false, default: null, description: 'Logfire token' }
};

// Check if .env.test exists
const envTestPath = path.join(process.cwd(), '.env.test');
if (!fs.existsSync(envTestPath)) {
  console.log(colors.red + '✗ .env.test file not found!' + colors.reset);
  process.exit(1);
}

// Try to load dotenv (if available)
let dotenvLoaded = false;
try {
  require('dotenv').config({ path: envTestPath });
  dotenvLoaded = true;
  console.log(colors.green + '✓ .env.test loaded via dotenv' + colors.reset + '\n');
} catch (err) {
  console.log(colors.yellow + '⚠ dotenv not installed, using process.env only' + colors.reset);
  console.log(colors.gray + '  Install with: npm install dotenv' + colors.reset + '\n');
}

// Check each expected variable
let missingRequired = 0;
let missingOptional = 0;
let found = 0;
let canaryDetected = 0;

Object.entries(expectedVars).forEach(([name, config]) => {
  const value = process.env[name];
  const statusColor = value ? colors.green : (config.required ? colors.red : colors.yellow);
  const status = value ? '✓' : (config.required ? '✗' : '○');

  if (value) {
    found++;
    // Check for canary/test values
    if (value.includes('CANARY') || value.includes('canary')) {
      canaryDetected++;
    }
  } else if (config.required) {
    missingRequired++;
  } else {
    missingOptional++;
  }

  console.log(statusColor + status + colors.reset + ' ' + colors.cyan + name.padEnd(25) + colors.reset);

  if (value) {
    // Mask sensitive values
    const masked = isSensitive(name) ? maskValue(value) : value;
    console.log(colors.gray + '  Value: '.padEnd(10) + masked + colors.reset);

    if (value.includes('CANARY')) {
      console.log(colors.yellow + '  ⚠ Canary detection token' + colors.reset);
    }
  } else if (config.default) {
    console.log(colors.gray + '  Default: ' + config.default + ' (will be used)' + colors.reset);
  } else {
    console.log(colors.gray + '  Not set' + colors.reset);
  }

  if (config.description) {
    console.log(colors.gray + '  ' + config.description + colors.reset);
  }

  console.log('');
});

// Summary
console.log(colors.cyan + '─'.repeat(60) + colors.reset);
console.log(colors.cyan + 'SUMMARY' + colors.reset);
console.log(colors.cyan + '─'.repeat(60) + colors.reset + '\n');

console.log('Variables found:  ' + colors.green + found + colors.reset);
console.log('Missing required: ' + (missingRequired > 0 ? colors.red + missingRequired : colors.green + missingRequired) + colors.reset);
console.log('Missing optional: ' + colors.yellow + missingOptional + colors.reset);
console.log('Canary tokens:    ' + colors.yellow + canaryDetected + colors.reset + '\n');

// Check .env file
const envPath = path.join(process.cwd(), '.env');
const envExists = fs.existsSync(envPath);
console.log('.env file exists: ' + (envExists ? colors.green + 'Yes' : colors.gray + 'No') + colors.reset);
if (envExists) {
  console.log(colors.gray + '  ⚠ Ensure .env is in .gitignore!' + colors.reset);
}
console.log('.env.test exists: ' + colors.green + 'Yes' + colors.reset);
console.log('dotenv available: ' + (dotenvLoaded ? colors.green + 'Yes' : colors.red + 'No') + colors.reset + '\n');

// Check codebase references
console.log(colors.cyan + '─'.repeat(60) + colors.reset);
console.log(colors.cyan + 'CODE REFERENCES' + colors.reset);
console.log(colors.cyan + '─'.repeat(60) + colors.reset + '\n');

const appContent = fs.readFileSync('app.js', 'utf8');
const appImprovedContent = fs.existsSync('app_improved.js') 
  ? fs.readFileSync('app_improved.js', 'utf8')
  : '';

const inApp = (appContent.match(/process\.env\./g) || []).length;
const inImproved = (appImprovedContent.match(/process\.env\./g) || []).length;

console.log('app.js references:           ' + colors.gray + inApp + colors.reset);
console.log('app_improved.js references:  ' + colors.green + inImproved + colors.reset);

if (inApp === 0 && inImproved > 0) {
  console.log(colors.yellow + '  → app_improved.js uses env vars, app.js does not' + colors.reset);
}

console.log('\n' + colors.cyan + '═'.repeat(60) + colors.reset + '\n');

// Warn if dotenv is not installed but needed
if (inImproved > 0 && !dotenvLoaded) {
  console.log(colors.yellow + '⚠ WARNING:' + colors.reset);
  console.log('app_improved.js uses environment variables but dotenv is not installed.');
  console.log(colors.gray + 'Install with: npm install dotenv' + colors.reset);
  console.log(colors.gray + 'Add to app: require("dotenv").config({ path: ".env.test" });' + colors.reset + '\n');
}

// Recommendations
console.log(colors.cyan + 'RECOMMENDATIONS:' + colors.reset);
if (inImproved > 0) {
  console.log(colors.green + '✓' + colors.reset + ' Update .env.test to include NODE_ENV and PORT');
}
if (canaryDetected > 0) {
  console.log(colors.green + '✓' + colors.reset + ' Canary tokens present (good for exfiltration detection)');
}
if (!envExists) {
  console.log(colors.green + '✓' + colors.reset + ' Create .env file for local development');
}
console.log(colors.green + '✓' + colors.reset + ' Add .env to .gitignore');
console.log(colors.green + '✓' + colors.reset + ' Create .env.example for documentation\n');

process.exit(missingRequired > 0 ? 1 : 0);

// Helper functions
function isSensitive(name) {
  const sensitiveKeys = ['KEY', 'SECRET', 'TOKEN', 'PASSWORD', 'CREDENTIAL'];
  return sensitiveKeys.some(key => name.includes(key));
}

function maskValue(value) {
  if (!value || value.length < 8) return '***';
  return value.substring(0, 4) + '***' + value.substring(value.length - 4);
}

