#!/usr/bin/env node

/**
 * Credential Verification Script
 * Checks connectivity to external services using credentials from .env.test
 * 
 * WARNING: This script actively tests credentials against external services.
 * Only run this in a controlled environment with proper authorization.
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const https = require('https');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m'
};

// Test results
const results = {
  passed: [],
  failed: [],
  skipped: [],
  warnings: []
};

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logTest(name, status, details = '') {
  const statusColors = {
    PASS: 'green',
    FAIL: 'red',
    SKIP: 'yellow',
    WARN: 'yellow'
  };
  const icon = {
    PASS: '✓',
    FAIL: '✗',
    SKIP: '○',
    WARN: '⚠'
  };

  log(`${statusColors[status]}${icon[status]} ${name}${colors.reset}`, statusColors[status]);
  if (details) {
    log(`  ${details}`, 'gray');
  }
}

// =========================================
// 1. Database URL Validation
// =========================================
async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    logTest('Database URL', 'SKIP', 'DATABASE_URL not set');
    results.skipped.push({ test: 'Database URL', reason: 'Not configured' });
    return;
  }

  logTest('Database URL Validation', 'WARN', 'Testing database connectivity...');

  // Check for canary token
  if (dbUrl.includes('CANARY')) {
    log('  → Detected canary token in database URL', 'yellow');
    results.warnings.push({
      test: 'Database URL',
      message: 'Contains canary token - likely a test placeholder'
    });
  }

  try {
    const pool = new Pool({
      connectionString: dbUrl,
      connectionTimeoutMillis: 5000,
      max: 1
    });

    const client = await pool.connect();

    try {
      const result = await client.query('SELECT version()');
      const version = result.rows[0].version;

      logTest('Database Connection', 'PASS', `PostgreSQL ${version.split(' ')[1]}`);
      results.passed.push({ test: 'Database Connection', details: `Version: ${version.split(' ')[1]}` });

      // Test basic query
      const nowResult = await client.query('SELECT NOW()');
      logTest('Database Query', 'PASS', `Server time: ${nowResult.rows[0].now}`);
      results.passed.push({ test: 'Database Query', details: 'SELECT NOW() successful' });

    } finally {
      client.release();
      await pool.end();
    }
  } catch (error) {
    const errorMsg = error.message;
    logTest('Database Connection', 'FAIL', errorMsg);

    if (errorMsg.includes('authentication failed') || errorMsg.includes('password authentication failed')) {
      log('  → Credential appears valid but wrong password', 'yellow');
    } else if (errorMsg.includes('connection refused') || errorMsg.includes('ECONNREFUSED')) {
      log('  → Host unreachable or port not open', 'yellow');
    } else if (errorMsg.includes('getaddrinfo') || errorMsg.includes('ENOTFOUND')) {
      log('  → Hostname does not resolve', 'yellow');
    }

    results.failed.push({ test: 'Database Connection', error: errorMsg });
  }
}

// =========================================
// 2. AWS Credentials Validation
// =========================================
function validateAWSCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    logTest('AWS Credentials', 'SKIP', 'AWS credentials not set');
    results.skipped.push({ test: 'AWS Credentials', reason: 'Not configured' });
    return;
  }

  logTest('AWS Credentials', 'WARN', 'Checking AWS credential format...');

  // Check for canary tokens
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    log('  → Detected canary token in AWS credentials', 'yellow');
    results.warnings.push({
      test: 'AWS Credentials',
      message: 'Contains canary token - likely a test placeholder'
    });
  }

  // AWS Access Key ID format validation (20 alphanumeric chars)
  const akiPattern = /^AKIA[A-Z0-9]{16}$/;
  const legacyPattern = /^[A-Z0-9]{20}$/;

  if (akiPattern.test(accessKeyId) || legacyPattern.test(accessKeyId)) {
    logTest('AWS Access Key ID Format', 'PASS', 'Valid format pattern');
    results.passed.push({ test: 'AWS Access Key ID Format', details: accessKeyId });
  } else {
    logTest('AWS Access Key ID Format', 'FAIL', 'Invalid format (should be 20 chars)');
    results.failed.push({ 
      test: 'AWS Access Key ID Format', 
      error: 'Does not match AWS key format pattern' 
    });
  }

  // AWS Secret Access Key format validation (40 chars base64-like)
  if (secretAccessKey.length === 40) {
    logTest('AWS Secret Key Format', 'PASS', 'Valid length (40 characters)');
    results.passed.push({ test: 'AWS Secret Key Format', details: 'Length: 40 chars' });
  } else {
    logTest('AWS Secret Key Format', 'FAIL', `Invalid length (${secretAccessKey.length} chars, expected 40)`);
    results.failed.push({ 
      test: 'AWS Secret Key Format', 
      error: `Invalid length: ${secretAccessKey.length}` 
    });
  }
}

// =========================================
// 3. Anthropic API Key Validation
// =========================================
async function testAnthropicAPI() {
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    logTest('Anthropic API Key', 'SKIP', 'ANTHROPIC_API_KEY not set');
    results.skipped.push({ test: 'Anthropic API Key', reason: 'Not configured' });
    return;
  }

  logTest('Anthropic API Key', 'WARN', 'Testing Anthropic API...');

  // Check for canary token
  if (apiKey.includes('CANARY')) {
    log('  → Detected canary token in API key', 'yellow');
    results.warnings.push({
      test: 'Anthropic API Key',
      message: 'Contains canary token - likely a test placeholder'
    });
  }

  // Anthropic API key format validation
  const keyPattern = /^sk-ant-[a-zA-Z0-9_-]{95,}$/;

  if (keyPattern.test(apiKey)) {
    logTest('Anthropic API Key Format', 'PASS', 'Valid key format');
    results.passed.push({ test: 'Anthropic API Key Format', details: 'Pattern matches' });
  } else {
    logTest('Anthropic API Key Format', 'FAIL', 'Invalid format');
    results.failed.push({ 
      test: 'Anthropic API Key Format', 
      error: 'Does not match Anthropic key format' 
    });
  }

  // Test actual API call
  try {
    const data = JSON.stringify({
      model: "claude-3-haiku-20240307",
      max_tokens: 10,
      messages: [{ role: "user", content: "Hi" }]
    });

    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    await new Promise((resolve, reject) => {
      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', chunk => body += chunk);
        res.on('end', () => {
          if (res.statusCode === 200 || res.statusCode === 201) {
            logTest('Anthropic API Call', 'PASS', `Status: ${res.statusCode}`);
            results.passed.push({ test: 'Anthropic API Call', details: `HTTP ${res.statusCode}` });
          } else if (res.statusCode === 401) {
            logTest('Anthropic API Call', 'FAIL', 'Authentication failed (401)');
            results.failed.push({ test: 'Anthropic API Call', error: '401 Unauthorized' });
          } else if (res.statusCode === 429) {
            logTest('Anthropic API Call', 'WARN', 'Rate limited (429) - Key may be valid');
            results.warnings.push({ test: 'Anthropic API Call', message: 'Rate limited - key appears valid' });
          } else {
            logTest('Anthropic API Call', 'WARN', `Unexpected status: ${res.statusCode}`);
            results.warnings.push({ test: 'Anthropic API Call', message: `HTTP ${res.statusCode}` });
          }
          resolve();
        });
      });

      req.on('error', (error) => {
        logTest('Anthropic API Call', 'FAIL', error.message);
        results.failed.push({ test: 'Anthropic API Call', error: error.message });
        resolve();
      });

      req.write(data);
      req.end();
    });
  } catch (error) {
    logTest('Anthropic API Call', 'FAIL', error.message);
    results.failed.push({ test: 'Anthropic API Call', error: error.message });
  }
}

// =========================================
// 4. Stripe API Key Validation
// =========================================
async function testStripeAPI() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;

  if (!stripeKey) {
    logTest('Stripe Secret Key', 'SKIP', 'STRIPE_SECRET_KEY not set');
    results.skipped.push({ test: 'Stripe Secret Key', reason: 'Not configured' });
    return;
  }

  logTest('Stripe Secret Key', 'WARN', 'Testing Stripe API...');

  // Check for canary token
  if (stripeKey.includes('CANARY')) {
    log('  → Detected canary token in Stripe key', 'yellow');
    results.warnings.push({
      test: 'Stripe Secret Key',
      message: 'Contains canary token - likely a test placeholder'
    });
  }

  // Stripe key format validation
  // Test keys start with sk_test_, live with sk_live_
  const stripePattern = /^sk_(test|live)_[a-zA-Z0-9]{24,}$/;

  if (stripePattern.test(stripeKey)) {
    const keyType = stripeKey.startsWith('sk_test_') ? 'Test' : 'Live';
    logTest('Stripe Key Format', 'PASS', `Valid ${keyType} key format`);
    results.passed.push({ test: 'Stripe Key Format', details: keyType });
  } else {
    logTest('Stripe Key Format', 'FAIL', 'Invalid Stripe key format');
    results.failed.push({ 
      test: 'Stripe Key Format', 
      error: 'Does not match Stripe key format pattern' 
    });
  }

  // Test actual API call
  try {
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/balance',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${stripeKey}`
      }
    };

    await new Promise((resolve, reject) => {
      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', chunk => body += chunk);
        res.on('end', () => {
          if (res.statusCode === 200) {
            const data = JSON.parse(body);
            logTest('Stripe API Call', 'PASS', `Balance retrieved: ${data.object}`);
            results.passed.push({ test: 'Stripe API Call', details: 'Account balance retrieved' });
          } else if (res.statusCode === 401) {
            logTest('Stripe API Call', 'FAIL', 'Authentication failed (401)');
            results.failed.push({ test: 'Stripe API Call', error: '401 Unauthorized' });
          } else {
            logTest('Stripe API Call', 'WARN', `Unexpected status: ${res.statusCode}`);
            results.warnings.push({ test: 'Stripe API Call', message: `HTTP ${res.statusCode}` });
          }
          resolve();
        });
      });

      req.on('error', (error) => {
        logTest('Stripe API Call', 'FAIL', error.message);
        results.failed.push({ test: 'Stripe API Call', error: error.message });
        resolve();
      });

      req.end();
    });
  } catch (error) {
    logTest('Stripe API Call', 'FAIL', error.message);
    results.failed.push({ test: 'Stripe API Call', error: error.message });
  }
}

// =========================================
// 5. Logfire Token Validation
// =========================================
async function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    logTest('Logfire Token', 'SKIP', 'LOGFIRE_TOKEN not set');
    results.skipped.push({ test: 'Logfire Token', reason: 'Not configured' });
    return;
  }

  logTest('Logfire Token', 'WARN', 'Checking token...');

  // Check for canary token
  if (token.includes('CANARY')) {
    log('  → Detected canary token in Logfire token', 'yellow');
    results.warnings.push({
      test: 'Logfire Token',
      message: 'Contains canary token - likely a test placeholder'
    });
  }

  // Basic token format validation (should be non-empty and reasonable length)
  if (token.length >= 10) {
    logTest('Logfire Token Format', 'PASS', `Valid length (${token.length} chars)`);
    results.passed.push({ test: 'Logfire Token Format', details: `Length: ${token.length}` });
  } else {
    logTest('Logfire Token Format', 'WARN', `Unusually short token (${token.length} chars)`);
    results.warnings.push({ test: 'Logfire Token Format', message: `Short token: ${token.length} chars` });
  }

  // Logfire is typically for Python/other integrations - minimal check
  log('  → Logfire tokens are typically validated by the client library', 'gray');
}

// =========================================
// Main Execution
// =========================================
async function main() {
  console.log('\n' + colors.bright);
  console.log('╔═══════════════════════════════════════════════════════════╗');
  console.log('║     Credential Verification Script                        ║');
  console.log('║     Checking credentials from .env.test                    ║');
  console.log('╚═══════════════════════════════════════════════════════════╝');
  console.log(colors.reset);
  console.log('');

  log('Note: Some tests may trigger rate limits or authentication failures', 'yellow');
  log('for test/canary credentials. This is expected behavior.\n', 'yellow');

  try {
    // Database test
    log('\n' + colors.bright + '─ Testing Database Connection ──' + colors.reset);
    await testDatabaseConnection();

    // AWS credentials
    log('\n' + colors.bright + '─ Testing AWS Credentials ──' + colors.reset);
    validateAWSCredentials();

    // Anthropic API
    log('\n' + colors.bright + '─ Testing Anthropic API ──' + colors.reset);
    await testAnthropicAPI();

    // Stripe API
    log('\n' + colors.bright + '─ Testing Stripe API ──' + colors.reset);
    await testStripeAPI();

    // Logfire token
    log('\n' + colors.bright + '─ Testing Logfire Token ──' + colors.reset);
    await testLogfireToken();

  } catch (error) {
    log(`\nUnexpected error: ${error.message}`, 'red');
    console.error(error);
  }

  // Summary
  console.log('\n' + colors.bright);
  console.log('╔═══════════════════════════════════════════════════════════╗');
  console.log('║                        Summary                            ║');
  console.log('╚═══════════════════════════════════════════════════════════╝');
  console.log(colors.reset);

  const summary = [
    { label: 'Passed Tests', count: results.passed.length, color: 'green' },
    { label: 'Failed Tests', count: results.failed.length, color: 'red' },
    { label: 'Warnings', count: results.warnings.length, color: 'yellow' },
    { label: 'Skipped', count: results.skipped.length, color: 'gray' }
  ];

  summary.forEach(({ label, count, color }) => {
    log(`  ${label}:`.padEnd(20) + count.toString().padStart(4), color);
  });

  console.log('');

  // Detailed results
  if (results.warnings.length > 0) {
    log('Warnings:', 'yellow');
    results.warnings.forEach(({ test, message }) => {
      log(`  • ${test}: ${message}`, 'yellow');
    });
    console.log('');
  }

  if (results.failed.length > 0) {
    log('Failed Tests:', 'red');
    results.failed.forEach(({ test, error }) => {
      log(`  • ${test}: ${error}`, 'red');
    });
    console.log('');
  }

  // Recommendations
  log('Recommendations:', 'blue');

  const canaryCount = results.warnings.filter(w => w.message?.includes('canary')).length;
  if (canaryCount > 0) {
    log(`  • ${canaryCount} credential(s) contain canary tokens - These are likely test place holders`, 'blue');
    log('    Consider removing if not used in the application', 'blue');
  }

  if (results.passed.length === 0) {
    log('  • No credentials validated successfully - All may be stale or invalid', 'blue');
  }

  if (results.skipped.length > 0) {
    log(`  • ${results.skipped.length} test(s) skipped - Credentials not configured`, 'blue');
  }

  console.log('');
}

// Run the script
main().catch(console.error);

{
  "name": "app-credential-verification",
  "version": "1.0.0",
  "description": "Simple Express app with credential verification",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "verify": "node verify-credentials.js"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
