#!/usr/bin/env node

/**
 * Credential Verification Script (Standalone Version)
 * Checks API keys and credentials format without external dependencies
 * Uses Node.js built-in https module for API tests
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m'
};

// Load .env.test manually
function loadEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      const match = line.match(/^([^#]+)=(.*)$/);
      if (match) {
        const [, key, ...valueParts] = match;
        const value = valueParts.join('=').trim();
        // Remove quotes if present
        env[key.trim()] = value.replace(/^["']|["']$/g, '');
      }
    });
  } catch (error) {
    console.error(`Warning: Could not load ${filePath}: ${error.message}`);
  }
  return env;
}

// Test results storage
const results = {
  passed: [],
  failed: [],
  skipped: [],
  warnings: []
};

// Logging functions
function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function logTest(name, status, details = '') {
  const statusColors = {
    PASS: 'green',
    FAIL: 'red',
    SKIP: 'yellow',
    WARN: 'yellow'
  };
  const icon = {
    PASS: '✓',
    FAIL: '✗',
    SKIP: '○',
    WARN: '⚠'
  };

  log(`${statusColors[status]}${icon[status]} ${name}${colors.reset}`, statusColors[status]);
  if (details) {
    log(`  ${details}`, 'gray');
  }
}

// =========================================
// Test Functions
// =========================================

function testDatabaseURL() {
  const dbUrl = process.env.DATABASE_URL || env.DATABASE_URL;

  logTest('Database URL Check', 'WARN', 'Analyzing...');

  if (!dbUrl) {
    logTest('DATABASE_URL', 'SKIP', 'Not set in .env.test');
    results.skipped.push({ test: 'DATABASE_URL', reason: 'Not configured' });
    return;
  }

  // Check for canary token
  if (dbUrl.includes('CANARY')) {
    log('  → ⚠️ Canary token detected', 'yellow');
    results.warnings.push({
      test: 'DATABASE_URL',
      message: 'Contains CANARY - test placeholder, not a real credential'
    });
  }

  // Parse connection string
  const urlMatch = dbUrl.match(/^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/);
  if (urlMatch) {
    const [, user, password, host, port, database] = urlMatch;
    log(`  → User: ${user}`, 'gray');
    log(`  → Host: ${host}:${port}`, 'gray');
    log(`  → Database: ${database}`, 'gray');

    results.passed.push({ 
      test: 'DATABASE_URL Format',
      details: `Valid PostgreSQL URL format to ${host}`
    });
    logTest('DATABASE_URL Format', 'PASS', 'Valid PostgreSQL connection string format');
  } else {
    results.failed.push({ 
      test: 'DATABASE_URL Format',
      error: 'Invalid PostgreSQL connection string format'
    });
    logTest('DATABASE_URL Format', 'FAIL', 'Invalid PostgreSQL URL format');
  }
}

function testAWSCredentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID || env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY || env.AWS_SECRET_ACCESS_KEY;

  logTest('AWS Credentials Check', 'WARN', 'Analyzing...');

  if (!accessKeyId || !secretAccessKey) {
    logTest('AWS Credentials', 'SKIP', 'Not both set in .env.test');
    results.skipped.push({ test: 'AWS Credentials', reason: 'Not configured' });
    return;
  }

  // Check for canary tokens
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    log('  → ⚠️ Canary token detected', 'yellow');
    results.warnings.push({
      test: 'AWS Credentials',
      message: 'Contains CANARY - test placeholder, not a real credential'
    });
  }

  // AWS Access Key ID: 20 alphanumeric chars, often starts with AKIA
  const akiPattern = /^AKIA[A-Z0-9]{16}$/;
  const legacyPattern = /^[A-Z0-9]{20}$/;

  if (akiPattern.test(accessKeyId)) {
    logTest('AWS Access Key ID', 'PASS', 'Valid AKIA format (20 chars)');
    results.passed.push({ test: 'AWS Access Key ID', details: 'AKIA format verified' });
  } else if (legacyPattern.test(accessKeyId)) {
    logTest('AWS Access Key ID', 'PASS', 'Valid legacy format (20 chars)');
    results.passed.push({ test: 'AWS Access Key ID', details: 'Legacy format verified' });
  } else {
    log(`  → Key ID format: ${accessKeyId}`, 'gray');
    logTest('AWS Access Key ID', 'FAIL', 'Invalid AWS format (expected 20 alphanumeric chars)');
    results.failed.push({ test: 'AWS Access Key ID', error: 'Invalid format' });
  }

  // AWS Secret Access Key: 40 chars (base64-like)
  if (secretAccessKey.length === 40) {
    logTest('AWS Secret Access Key', 'PASS', 'Valid length (40 characters)');
    results.passed.push({ test: 'AWS Secret Access Key', details: 'Length: 40 chars' });
  } else {
    log(`  → Secret length: ${secretAccessKey.length} chars`, 'gray');
    logTest('AWS Secret Access Key', 'FAIL', `Invalid length (expected 40, got ${secretAccessKey.length})`);
    results.failed.push({ test: 'AWS Secret Access Key', error: `Length ${secretAccessKey.length}` });
  }
}

async function testAnthropicAPI() {
  const apiKey = process.env.ANTHROPIC_API_KEY || env.ANTHROPIC_API_KEY;

  logTest('Anthropic API Key', 'WARN', 'Testing...');

  if (!apiKey) {
    logTest('Anthropic API Key', 'SKIP', 'Not set in .env.test');
    results.skipped.push({ test: 'Anthropic API Key', reason: 'Not configured' });
    return;
  }

  // Check for canary token
  if (apiKey.includes('CANARY')) {
    log('  → ⚠️ Canary token detected', 'yellow');
    results.warnings.push({
      test: 'Anthropic API Key',
      message: 'Contains CANARY - test placeholder, not a real credential'
    });
  }

  // Anthropic API key format: sk-ant- followed by 95+ chars
  const keyPattern = /^sk-ant-[a-zA-Z0-9_-]{95,}$/;

  if (keyPattern.test(apiKey)) {
    logTest('Anthropic Key Format', 'PASS', 'Valid sk-ant format (100+ chars total)');
    results.passed.push({ test: 'Anthropic Key Format', details: `Length: ${apiKey.length} chars` });
  } else {
    log(`  → Key format: ${apiKey.substring(0, 20)}...`, 'gray');
    logTest('Anthropic Key Format', 'FAIL', `Invalid Anthropic format (expected REDACTED_ANTHROPIC_KEY... with 100+ chars)`);
    results.failed.push({ test: 'Anthropic Key Format', error: `Length: ${apiKey.length}, invalid pattern` });
  }

  // Test API call (if not a canary)
  if (!apiKey.includes('CANARY')) {
    try {
      const data = JSON.stringify({
        model: "claude-3-haiku-20240307",
        max_tokens: 10,
        messages: [{ role: "user", content: "Hi" }]
      });

      await new Promise((resolve) => {
        const req = https.request({
          hostname: 'api.anthropic.com',
          port: 443,
          path: '/v1/messages',
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
            'Content-Length': Buffer.byteLength(data)
          },
          timeout: 5000
        }, (res) => {
          let body = '';
          res.on('data', chunk => body += chunk);
          res.on('end', () => {
            if (res.statusCode === 200 || res.statusCode === 201) {
              logTest('Anthropic API Call', 'PASS', `HTTP ${res.statusCode}`);
              results.passed.push({ test: 'Anthropic API Call', details: `HTTP ${res.statusCode}` });
            } else if (res.statusCode === 401) {
              logTest('Anthropic API Call', 'FAIL', '401 Unauthorized - Invalid key');
              results.failed.push({ test: 'Anthropic API Call', error: '401 Unauthorized' });
            } else {
              logTest('Anthropic API Call', 'WARN', `HTTP ${res.statusCode}`);
              results.warnings.push({ test: 'Anthropic API Call', message: `HTTP ${res.statusCode}` });
            }
            resolve();
          });
        });

        req.on('error', (error) => {
          logTest('Anthropic API Call', 'FAIL', error.message);
          results.failed.push({ test: 'Anthropic API Call', error: error.message });
          resolve();
        });

        req.on('timeout', () => {
          req.destroy();
          logTest('Anthropic API Call', 'WARN', 'Request timeout');
          results.warnings.push({ test: 'Anthropic API Call', message: 'Timeout' });
          resolve();
        });

        req.write(data);
        req.end();
      });
    } catch (error) {
      logTest('Anthropic API Call', 'FAIL', error.message);
      results.failed.push({ test: 'Anthropic API Call', error: error.message });
    }
  } else {
    log('  → Skipping API call for canary token', 'gray');
  }
}

async function testStripeAPI() {
