              results.passed.push({ test: 'Stripe API Call', details: 'Balance retrieved' });
            } else if (res.statusCode === 401) {
              logTest('Stripe API Call', 'FAIL', '401 Unauthorized - Invalid key');
              results.failed.push({ test: 'Stripe API Call', error: '401 Unauthorized' });
            } else {
