            }
            resolve();
          });
        });

        req.on('error', (error) => {
          logTest('Stripe API Call', 'FAIL', error.message);
          results.failed.push({ test: 'Stripe API Call', error: error.message });
          resolve();
        });

        req.on('timeout', () => {
          req.destroy();
          logTest('Stripe API Call', 'WARN', 'Request timeout');
          results.warnings.push({ test: 'Stripe API Call', message: 'Timeout' });
          resolve();
        });

        req.end();
      });
    } catch (error) {
      logTest('Stripe API Call', 'FAIL', error.message);
      results.failed.push({ test: 'Stripe API Call', error: error.message });
    }
  } else {
    log('  → Skipping API call for canary token', 'gray');
  }
}

function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN || env.LOGFIRE_TOKEN;

  logTest('Logfire Token', 'WARN', 'Checking...');

  if (!token) {
