// Security-hardened Express application
// Includes comprehensive error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. HTTP security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
}));

// 2. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime,
    });
  },
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for user routes
const userApiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30, // Lower limit for user data
  message: { error: 'Too many user requests' },
});

// 3. Request body parsing with size limits
app.use(express.json({
  limit: '10kb', // Prevent large payloads
  strict: true, // Only accept objects and arrays
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
}));

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

// Sanitization helpers
const sanitizeQuery = (req, res, next) => {
  // Remove null/undefined from query
  Object.keys(req.query).forEach(key => {
    if (req.query[key] === null || req.query[key] === undefined) {
      delete req.query[key];
    }
    // Trim string values
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].trim();
    }
  });
  next();
};

// ============================================
// CUSTOM ERROR HANDLING
// ============================================

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Custom error class
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Route not found: ${req.method} ${req.path}`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: err.message || 'Internal server error',
    timestamp: new Date().toISOString(),
    path: req.path,
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.details = err.details || null;
  }

  // Handle specific error types
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or expired authentication token',
    });
  }

  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON',
    });
  }

  // Send error response
  res.status(statusCode).json(errorResponse);
});

// ============================================
// REQUEST LOGGING
// ============================================

app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(JSON.stringify({
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString(),
    }));
  });

  next();
});

// ============================================
// HEALTH CHECK ENDPOINT
// ============================================

app.get('/health', [
  // Validate query parameters (if any)
  query('verbose')
    .optional()
    .isIn(['true', 'false', '1', '0'])
    .withMessage('verbose must be true or false'),
  handleValidationErrors,
], asyncHandler(async (req, res) => {
  const health = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  };

  // Add verbose info if requested
  if (req.query.verbose === 'true' || req.query.verbose === '1') {
    health.environment = process.env.NODE_ENV || 'development';
    health.version = process.env.npm_package_version || '1.0.0';
    health.nodeVersion = process.version;
    health.memory = process.memoryUsage();
  }

  res.json(health);
}));

// ============================================
// USERS ENDPOINTS
// ============================================

// Get all users with pagination and filtering
app.get('/users', [
  userApiLimiter,
  sanitizeQuery,

  // Validate query parameters
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('page must be a positive integer')
    .toInt(),

  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100')
    .toInt(),

  query('sort')
    .optional()
    .matches(/^(name|email|id):(asc|desc)$/i)
    .withMessage('sort must be in format: field:direction (e.g., name:asc)'),

  query('search')
    .optional()
    .isLength({ max: 100 })
    .withMessage('search term must be less than 100 characters')
    .trim(),

  handleValidationErrors,
], asyncHandler(async (req, res) => {
  // Extract and validate parameters
  const page = req.query.page || 1;
  const limit = req.query.limit || 10;
  const sort = req.query.sort || 'id:asc';
  const search = req.query.search;

  // Simulated database query with safety checks
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
    { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
  ];

  // Apply search filter (with input sanitization)
  let filteredUsers = allUsers;
  if (search) {
    const searchRegex = new RegExp(
      search.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), // Escape regex special chars
      'i'
    );
    filteredUsers = allUsers.filter(user => 
      searchRegex.test(user.name) || searchRegex.test(user.email)
    );
  }

  // Apply sorting
  const [sortField, sortDirection] = sort.split(':');
  const sortedUsers = [...filteredUsers].sort((a, b) => {
    const aVal = a[sortField];
    const bVal = b[sortField];
    return sortDirection === 'desc' 
      ? bVal.localeCompare(aVal) 
      : aVal.localeCompare(bVal);
  });

  // Apply pagination
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

  // Return response with metadata
  res.json({
    data: paginatedUsers,
    meta: {
      page,
      limit,
      total: filteredUsers.length,
      totalPages: Math.ceil(filteredUsers.length / limit),
      hasMore: endIndex < filteredUsers.length,
    },
    links: {
      self: `${req.path}?page=${page}&limit=${limit}`,
      next: endIndex < filteredUsers.length 
        ? `${req.path}?page=${page + 1}&limit=${limit}` 
        : null,
      prev: page > 1 ? `${req.path}?page=${page - 1}&limit=${limit}` : null,
    },
  });
}));

// Get single user by ID
app.get('/users/:id', [
  userApiLimiter,

  // Validate path parameter
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),

  handleValidationErrors,
], asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Simulated database
  const users = {
    1: { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
    2: { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
  };

  const user = users[userId];

  if (!user) {
    throw new AppError('User not found', 404);
  }

  res.json({ data: user });
}));

// Health check for monitoring (doesn't count against rate limit)
app.get('/health/live', (req, res) => {
  res.status(200).json({ status: 'alive' });
});

app.get('/health/ready', (req, res) => {
  // Add readiness checks here (e.g., database connection)
  res.status(200).json({ status: 'ready' });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close((err) => {
    if (err) {
      console.error('Error closing server:', err);
      process.exit(1);
    }
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

