    it('should validate verbose parameter - reject invalid values', async () => {
      const response = await request(app).get('/health?verbose=invalid');
      expect(response.status).toBe(400);
      expect(response.body).toHaveProperty('error', 'Validation failed');
    });

    it('should accept valid verbose parameter values', async () => {
      const response = await request(app).get('/health?verbose=true');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('memory');
    });
  });

  describe('Users Endpoint - Input Validation', () => {
    it('should return paginated users by default', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('data');
      expect(response.body).toHaveProperty('meta');
      expect(response.body.meta).toHaveProperty('page');
      expect(response.body.meta).toHaveProperty('limit');
      expect(response.body.meta).toHaveProperty('total');
    });

    it('should validate page parameter - reject negative numbers', async () => {
      const response = await request(app).get('/users?page=-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    it('should validate page parameter - reject non-numeric', async () => {
      const response = await request(app).get('/users?page=abc');
      expect(response.status).toBe(400);
    });

    it('should validate limit parameter - reject values > 100', async () => {
      const response = await request(app).get('/users?limit=101');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    it('should validate limit parameter - reject negative numbers', async () => {
      const response = await request(app).get('/users?limit=-5');
      expect(response.status).toBe(400);
    });

    it('should validate sort parameter format', async () => {
      const response = await request(app).get('/users?sort=invalid');
      expect(response.status).toBe(400);
    });

    it('should accept valid sort parameter', async () => {
      const response = await request(app).get('/users?sort=name:asc');
      expect(response.status).toBe(200);
    });

    it('should validate search parameter length', async () => {
      const longSearch = 'a'.repeat(101);
      const response = await request(app).get(`/users?search=${longSearch}`);
      expect(response.status).toBe(400);
    });

    it('should escape special regex characters in search', async () => {
      const response = await request(app).get('/users?search=test[.*]');
      expect(response.status).toBe(200);
    });
  });

  describe('Single User Endpoint', () => {
    it('should validate user ID is a positive integer', async () => {
      const response = await request(app).get('/users/abc');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    it('should validate user ID reject negative numbers', async () => {
      const response = await request(app).get('/users/-1');
      expect(response.status).toBe(400);
    });

    it('should validate user ID reject zero', async () => {
      const response = await request(app).get('/users/0');
      expect(response.status).toBe(400);
    });

    it('should return 404 for non-existent user', async () => {
      const response = await request(app).get('/users/999');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('User not found');
    });

    it('should return user data for valid ID', async () => {
      const response = await request(app).get('/users/1');
      expect(response.status).toBe(200);
      expect(response.body.data).toHaveProperty('id', 1);
      expect(response.body.data).toHaveProperty('name');
      expect(response.body.data).not.toHaveProperty('password');
    });
  });

  describe('Security Headers', () => {
    it('should set X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

