      expect([413, 404]).toContain(response.status);
    });
  });

  describe('HTTP Methods', () => {
    it('should reject unsupported methods on user endpoints', async () => {
      const response = await request(app).post('/users');
      expect([404, 405]).toContain(response.status);
    });
  });

  describe('Health Check Variants', () => {
    it('should return alive status', async () => {
      const response = await request(app).get('/health/live');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'alive');
    });

    it('should return ready status', async () => {
      const response = await request(app).get('/health/ready');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ready');
    });
  });

  describe('Input Sanitization', () => {
    it('should trim whitespace from query parameters', async () => {
      const response = await request(app).get('/users?search=  alice  ');
      expect(response.status).toBe(200);
    });

    it('should handle null and undefined query parameters', async () => {
      const response = await request(app).get('/users?test=&search');
      expect(response.status).toBe(200);
    });
  });
});

