#!/usr/bin/env node

/**
 * Environment Variable Validator
 * 
 * This script validates environment variables without testing credentials.
 * It checks for proper format and required fields only.
 * 
 * Does NOT make any network requests or attempt authentication.
 */

require('dotenv').config();

// Color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m',
};

function colorize(text, color) {
  return `${colors[color]}${text}${colors.reset}`;
}

// Validation patterns (format only, NOT validation against services)
const validators = {
  DATABASE_URL: {
    format: /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^/]+$/,
    description: 'PostgreSQL connection string',
    urgency: 'high',
  },
  AWS_ACCESS_KEY_ID: {
    format: /^AKIA[0-9A-Z]{16}$/,
    description: 'AWS access key ID',
    urgency: 'high',
  },
  AWS_SECRET_ACCESS_KEY: {
    format: /^[A-Za-z0-9/+=]{40}$/,
    description: 'AWS secret access key',
    urgency: 'high',
  },
  ANTHROPIC_API_KEY: {
    format: /^REDACTED_ANTHROPIC_KEY[A-Za-z0-9_-]{95}$/,
    description: 'Anthropic Claude API key',
    urgency: 'high',
  },
  STRIPE_SECRET_KEY: {
    format: /^sk_(live|test)_[0-9a-zA-Z]{24,}$/,
    description: 'Stripe API secret key',
    urgency: 'high',
  },
  LOGFIRE_TOKEN: {
    format: /^[0-9a-fA-F]{64}$/,
    description: 'Logfire authentication token',
    urgency: 'low',
  },
  NODE_ENV: {
    format: /^(development|test|staging|production)$/,
    description: 'Application environment',
    urgency: 'medium',
  },
  PORT: {
    format: /^\d{1,5}$/,
    description: 'Server port number',
    urgency: 'low',
  },
};

function detectCanaryTokens() {
  console.log(colorize('\n═══════════════════════════════════════════════════════════', 'blue'));
  console.log(colorize('🔍 CANARY TOKEN DETECTION', 'blue'));
  console.log(colorize('═══════════════════════════════════════════════════════════', 'blue'));

  const canaryPatterns = [
    /canary/i,
    /test-secret/i,
    /placeholder/i,
    /example/i,
    /xxx+/,
    /your_.*_key/i,
    /change.*me/i,
  ];

  let canaryFound = false;
  let suspiciousVars = [];

  Object.keys(process.env).forEach(key => {
    if (key.includes('SECRET') || key.includes('KEY') || key.includes('PASSWORD') || key.includes('TOKEN')) {
      const value = process.env[key];

      canaryPatterns.forEach(pattern => {
        if (pattern.test(value)) {
          canaryFound = true;
          suspiciousVars.push({ key, reason: pattern.toString() });
        }
      });
    }
  });

  if (suspiciousVars.length > 0) {
    console.log(colorize('\n⚠️  WARNING: Possible canary/test credentials detected:', 'yellow'));
    suspiciousVars.forEach(({ key, reason }) => {
      const displayValue = process.env[key].substring(0, 20) + '...';
      console.log(colorize(`   - ${key}: "${displayValue}"`, 'gray'));
      console.log(colorize(`     Reason: matches pattern ${reason}`, 'gray'));
    });
    console.log(colorize('\n   These appear to be synthetic test credentials.', 'yellow'));
    console.log(colorize('   They should NOT be used in production or tested against real services.', 'yellow'));
    console.log(colorize('   Attempting to use them may trigger security alerts.', 'red'));
  } else {
    console.log(colorize('\n✓ No obvious canary tokens detected', 'green'));
  }

  return canaryFound;
}

function validateEnvironment() {
  console.log(colorize('\n═══════════════════════════════════════════════════════════', 'blue'));
  console.log(colorize('📋 ENVIRONMENT VALIDATION', 'blue'));
  console.log(colorize('═══════════════════════════════════════════════════════════', 'blue'));

  const results = {
    valid: [],
    missing: [],
    invalid: [],
  };

  Object.keys(validators).forEach(key => {
    const value = process.env[key];
    const validator = validators[key];

    if (!value) {
      results.missing.push({ key, urgency: validator.urgency });
      console.log(colorize(`❌ ${key}`, 'red') + colorize(` - MISSING (${validator.urgency} priority)`, 'gray'));
    } else if (!validator.format.test(value)) {
      results.invalid.push({ key, description: validator.description });
      console.log(colorize(`⚠️  ${key}`, 'yellow') + colorize(` - INVALID FORMAT`, 'gray'));
      console.log(colorize(`   Expected: ${validator.description}`, 'gray'));
      console.log(colorize(`   Current: ${value.substring(0, 40)}${value.length > 40 ? '...' : ''}`, 'gray'));
    } else {
      results.valid.push(key);
      const masked = key.includes('SECRET') || key.includes('PASSWORD') || key.includes('TOKEN')
        ? value.substring(0, 8) + '...' + value.substring(value.length - 4)
        : value;
      console.log(colorize(`✓ ${key}`, 'green') + colorize(` = ${masked}`, 'gray'));
    }
  });

  return results;
}

function printSummary(results, hasCanary) {
  console.log(colorize('\n═══════════════════════════════════════════════════════════', 'blue'));
  console.log(colorize('📊 SUMMARY', 'blue'));
  console.log(colorize('═══════════════════════════════════════════════════════════', 'blue'));

  console.log(`\nValid:   ${colorize(results.valid.length.toString(), results.valid.length > 0 ? 'green' : 'gray')} variables`);
  console.log(`Missing: ${colorize(results.missing.length.toString(), results.missing.length > 0 ? 'yellow' : 'gray')} variables`);
  console.log(`Invalid: ${colorize(results.invalid.length.toString(), results.invalid.length > 0 ? 'red' : 'gray')} variables`);

  if (hasCanary) {
    console.log(colorize('\n⚠️  Canary tokens detected in environment variables', 'yellow'));
  }

  const hasHighUrgency = results.missing.some(m => m.urgency === 'high');
  const hasInvalid = results.invalid.length > 0;

  if (results.missing.length === 0 && results.invalid.length === 0 && !hasCanary) {
    console.log(colorize('\n✓ All environment variables are properly configured!', 'green'));
  } else if (hasHighUrgency || hasInvalid) {
    console.log(colorize('\n❌ Configuration has issues that need attention', 'red'));
    process.exit(1);
  } else {
    console.log(colorize('\n⚠️  Configuration needs attention', 'yellow'));
  }
}

function printRecommendations() {
  console.log(colorize('\n═══════════════════════════════════════════════════════════', 'blue'));
  console.log(colorize('💡 RECOMMENDATIONS', 'blue'));
  console.log(colorize('═══════════════════════════════════════════════════════════', 'blue'));

  console.log('\n1. ' + colorize('NEVER test credentials by making network requests', 'yellow'));
  console.log('   - This may trigger security alerts');
  console.log('   -credentials should be validated through configuration only');

  console.log('\n2. ' + colorize('Use proper secrets management', 'green'));
  console.log('   - AWS Secrets Manager, HashiCorp Vault, etc.');
  console.log('   - Never commit .env files to version control');

  console.log('\n3. ' + colorize('Rotate credentials regularly', 'green'));
  console.log('   - Implement credential rotation policies');
  console.log('   - Use short-lived tokens when possible');

  console.log('\n4. ' + colorize('Monitor for credential usage', 'green'));
  console.log('   - Use canary tokens for threat detection');
  console.log('   - Set up alerts for unauthorized access attempts');
}

// Main execution
console.log(colorize('\n🔐 Environment Variable Security Validator', 'blue'));

const hasCanary = detectCanaryTokens();
const results = validateEnvironment();
printSummary(results, hasCanary);
printRecommendations();

console.log(colorize('\n' + '='.repeat(59), 'gray') + '\n');

