// Improved application with security best practices and proper error handling
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit request body size to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Strict rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many attempts, please try again later.' },
});

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      }))
    });
  }
  next();
};

// Request logging middleware (in production, use proper logging library)
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Users endpoint with input validation
app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .trim()
      .escape()
      .isLength({ max: 100 })
      .withMessage('Search term must be <= 100 characters'),
    query('fields')
      .optional()
      .trim()
      .matches(/^[a-zA-Z0-9,_]+$/)
      .withMessage('Fields must contain only alphanumeric characters, commas, and underscores')
  ],
  validateRequest,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, search, fields } = req.query;

      // Mock user data (in production, fetch from database with parameterized queries)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      let filteredUsers = allUsers;

      // Apply search filter if provided
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      // Filter fields if specified
      let responseUsers = paginatedUsers;
      if (fields) {
        const requestedFields = fields.split(',');
        responseUsers = paginatedUsers.map(user => {
          const filtered = {};
          requestedFields.forEach(field => {
            if (user.hasOwnProperty(field)) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      res.json({
        data: responseUsers,
        meta: {
          total: filteredUsers.length,
          limit,
          offset,
          hasMore: offset + limit < filteredUsers.length
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        error: 'An error occurred while fetching users',
        requestId: req.id || 'unknown'
      });
    }
  }
);

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error details
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.id || 'unknown',
    timestamp: new Date().toISOString()
  });
});

// Start server using environment variable with fallback
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown handling
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

