## Additional Security Recommendations

### 1. Add Authentication/Authorization

```javascript
const jwt = require('express-jwt');
const unless = require('express-unless');

app.use(jwt({ secret: process.env.JWT_SECRET }).unless({ path: ['/health', '/api/public'] }));
```

### 2. Implement Proper Logging in Production

```javascript
const winston = require('winston');
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});
```

### 3. Add CORS Configuration

```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));
```

### 4. Implement Request IDs

```javascript
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

### 5. Add API Documentation with OpenAPI/Swagger

```javascript
const swaggerJsdoc = require('swagger-jsdoc');
const swaggerUi = require('swagger-ui-express');

const specs = swaggerJsdoc({
  definition: {
    openapi: '3.0.0',
    info: { title: 'API', version: '1.0.0' },
  },
  apis: ['./app.improved.js'],
});

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(specs));
```

### 6. Database Security (when adding database)

- Use parameterized queries / prepared statements
- Implement connection pooling
- Use least-privilege database credentials
- Encrypt sensitive data at rest

### 7. Add Security Tests

```javascript
// Example test with Jest and Supertest
describe('Security Tests', () => {
  test('should reject invalid limit parameter', async () => {
    const response = await request(app)
      .get('/users?limit=abc')
      .expect(400);
    expect(response.body.error).toBe('Validation failed');
  });

  test('should reject large payloads', async () => {
    const largePayload = 'x'.repeat(11 * 1024); // 11KB
    const response = await request(app)
      .post('/api/data')
      .send({ data: largePayload })
      .expect(413); // Payload Too Large
  });
});
```

