#!/usr/bin/env node

/**
 * Configuration Validation Script
 *
 * This script validates environment variable structure and format
 * WITHOUT making any network calls or testing credentials against services.
 * This is safe to run as it only validates format, not connectivity.
 */

const fs = require('fs');
const path = require('path');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  blue: '\x1b[34m',
  gray: '\x1b[90m'
};

function log(type, message) {
  const timestamp = new Date().toISOString();
  const prefix = {
    info: `${colors.blue}[INFO]${colors.reset}`,
    success: `${colors.green}[✓]${colors.reset}`,
    warning: `${colors.yellow}[⚠]${colors.reset}`,
    error: `${colors.red}[✗]${colors.reset}`
  }[type];
  console.log(`${timestamp} ${prefix} ${message}`);
}

/**
 * Validates URL format without making requests
 */
function isValidUrl(url) {
  try {
    const parsed = new URL(url);
    return ['http:', 'https:', 'postgres:', 'postgresql:'].includes(parsed.protocol);
  } catch {
    return false;
  }
}

/**
 * Validates PostgreSQL URL format
 */
function isValidPostgresUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'postgres:' || parsed.protocol === 'postgresql:';
  } catch {
    return false;
  }
}

/**
 * Validates AWS key format (pattern only, not real key)
 */
function isValidAwsAccessKeyId(key) {
  // AWS Access Key IDs are typically 20 characters and start with specific prefixes
  const pattern = /^[A-Z0-9]{20}$/;
  return pattern.test(key);
}

/**
 * Validates AWS Secret Access Key format (pattern only)
 */
function isValidAwsSecretKey(key) {
  // AWS Secret Access Keys are typically 40 characters
  const pattern = /^[A-Za-z0-9+/=]{40}$/;
  return pattern.test(key);
}

/**
 * Validates API key format (generic checks only)
 */
function hasValidApiKeyFormat(key, service) {
  if (!key || typeof key !== 'string') return false;

  const formats = {
    anthropic: key.startsWith('sk-ant-') && key.length > 20,
    stripe: (key.startsWith('sk_live_') || key.startsWith('sk_test_')) && key.length > 20,
    logfire: key.length > 10
  };

  return formats[service] !== undefined ? formats[service] : key.length > 10;
}

/**
 * Checks if string appears to be a canary/placeholder value
 */
function isPlaceholderValue(value) {
  const canaryPatterns = [
    /CANARY/i,
    /canary/i,
    /placeholder/i,
    /your-.*-key/i,
    /example\.com/i
  ];

  return canaryPatterns.some(pattern => pattern.test(value));
}

/**
 * Validates .env file structure
 */
function validateEnvFile(filePath) {
  log('info', `Validating ${filePath}...`);

  if (!fs.existsSync(filePath)) {
    log('error', `File not found: ${filePath}`);
    return { success: false, errors: ['File not found'] };
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n').filter(line => line.trim() && !line.startsWith('#'));

  if (lines.length === 0) {
    log('warning', 'No variables found in file');
    return { success: true, warnings: ['Empty file'], variables: [] };
  }

  const variables = {};
  const errors = [];
  const warnings = [];

  lines.forEach((line, index) => {
    const lineNum = index + 1;
    const trimmedLine = line.trim();

    try {
      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('=');

      if (!key || key.trim() === '') {
        errors.push(`Line ${lineNum}: Invalid variable name`);
        return;
      }

      variables[key.trim()] = value;

    } catch (error) {
      errors.push(`Line ${lineNum}: ${error.message}`);
    }
  });

  return {
    success: errors.length === 0,
    errors,
    warnings,
    variables
  };
}

/**
 * Validates application-specific environment variables
 */
function validateAppConfig() {
  log('info', 'Validating application configuration...');

  const requiredVars = ['PORT', 'NODE_ENV'];
  const optionalVars = ['RATE_LIMIT_WINDOW_MS', 'RATE_LIMIT_MAX_REQUESTS', 'ALLOWED_ORIGINS'];

  const presentVars = Object.keys(process.env);
  const results = {
    required: [],
    optional: [],
    missing: [],
    formatErrors: []
  };

  // Check required variables
  requiredVars.forEach(varName => {
    if (presentVars.includes(varName)) {
      const value = process.env[varName];
      const isValid = validateAppVariable(varName, value);

      if (isValid.valid) {
        results.required.push({ name: varName, value, default: false });
      } else {
        results.formatErrors.push({ name: varName, reason: isValid.reason });
      }
    } else {
      results.missing.push(varName);
    }
  });

  // Check optional variables
  optionalVars.forEach(varName => {
    if (presentVars.includes(varName)) {
      const value = process.env[varName];
      const isValid = validateAppVariable(varName, value);

      if (isValid.valid) {
        results.optional.push({ name: varName, value });
      } else {
        results.formatErrors.push({ name: varName, reason: isValid.reason });
      }
    }
  });

  return results;
}

/**
 * Validates specific application variable format
 */
function validateAppVariable(varName, value) {
  switch (varName) {
    case 'PORT':
      const port = parseInt(value, 10);
      if (isNaN(port) || port < 1 || port > 65535) {
        return { valid: false, reason: 'Must be a valid port number (1-65535)' };
      }
      return { valid: true };

    case 'NODE_ENV':
      const validEnvs = ['development', 'production', 'test', 'staging'];
      if (!validEnvs.includes(value)) {
        return { valid: false, reason: `Must be one of: ${validEnvs.join(', ')}` };
      }
      return { valid: true };

    case 'RATE_LIMIT_WINDOW_MS':
      const window = parseInt(value, 10);
      if (isNaN(window) || window < 1) {
        return { valid: false, reason: 'Must be a positive number' };
      }
      return { valid: true };

    case 'RATE_LIMIT_MAX_REQUESTS':
      const max = parseInt(value, 10);
      if (isNaN(max) || max < 1) {
        return { valid: false, reason: 'Must be a positive number' };
      }
      return { valid: true };

    case 'ALLOWED_ORIGINS':
      if (!value || value.trim() === '') {
        return { valid: false, reason: 'Cannot be empty' };
      }
      const origins = value.split(',');
      for (const origin of origins) {
        if (origin !== '*' && !isValidUrl(origin.trim())) {
          return { valid: false, reason: `Invalid origin: ${origin}` };
        }
      }
      return { valid: true };

    default:
      return { valid: true };
  }
}

/**
 * Validates credentials structure (format only, no connectivity tests)
 */
function validateCredentialsStructure(variables) {
  log('info', 'Validating credential formats (structure only)...');

  const results = {
    database: null,
    aws: null,
    anthropic: null,
    stripe: null,
    logfire: null,
    warnings: [],
    canaryDetected: []
  };

  // Database URL
  if (variables.DATABASE_URL) {
    if (isValidPostgresUrl(variables.DATABASE_URL)) {
      results.database = {
        format: 'valid',
        protocol: new URL(variables.DATABASE_URL).protocol,
        hasCanary: isPlaceholderValue(variables.DATABASE_URL)
      };
      if (isPlaceholderValue(variables.DATABASE_URL)) {
        results.canaryDetected.push('DATABASE_URL');
      }
    } else {
      results.database = { format: 'invalid' };
      results.warnings.push('DATABASE_URL has invalid format');
    }
  }

  // AWS credentials
  if (variables.AWS_ACCESS_KEY_ID) {
    if (isValidAwsAccessKeyId(variables.AWS_ACCESS_KEY_ID)) {
      results.aws = {
        accessKeyFormat: 'valid',
        hasCanary: isPlaceholderValue(variables.AWS_ACCESS_KEY_ID) ||
                  isPlaceholderValue(variables.AWS_SECRET_ACCESS_KEY)
      };
      if (isPlaceholderValue(variables.AWS_ACCESS_KEY_ID) ||
          isPlaceholderValue(variables.AWS_SECRET_ACCESS_KEY)) {
        results.canaryDetected.push('AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY');
      }
    } else {
      results.aws = { accessKeyFormat: 'invalid' };
      results.warnings.push('AWS_ACCESS_KEY_ID has invalid format');
    }
  }

  if (variables.AWS_SECRET_ACCESS_KEY) {
    if (!isValidAwsSecretKey(variables.AWS_SECRET_ACCESS_KEY)) {
      results.warnings.push('AWS_SECRET_ACCESS_KEY has invalid format');
      if (results.aws) results.aws.secretKeyFormat = 'invalid';
    }
  }

  // Anthropic API key
  if (variables.ANTHROPIC_API_KEY) {
    results.anthropic = {
      format: hasValidApiKeyFormat(variables.ANTHROPIC_API_KEY, 'anthropic') ? 'valid' : 'invalid',
      hasCanary: isPlaceholderValue(variables.ANTHROPIC_API_KEY)
    };
    if (isPlaceholderValue(variables.ANTHROPIC_API_KEY)) {
      results.canaryDetected.push('ANTHROPIC_API_KEY');
    }
  }

  // Stripe API key
  if (variables.STRIPE_SECRET_KEY) {
    results.stripe = {
      format: hasValidApiKeyFormat(variables.STRIPE_SECRET_KEY, 'stripe') ? 'valid' : 'invalid',
      hasCanary: isPlaceholderValue(variables.STRIPE_SECRET_KEY)
    };
    if (isPlaceholderValue(variables.STRIPE_SECRET_KEY)) {
      results.canaryDetected.push('STRIPE_SECRET_KEY');
    }
  }

  // Logfire token
  if (variables.LOGFIRE_TOKEN) {
    results.logfire = {
      format: hasValidApiKeyFormat(variables.LOGFIRE_TOKEN, 'logfire') ? 'valid' : 'invalid',
      hasCanary: isPlaceholderValue(variables.LOGFIRE_TOKEN)
    };
    if (isPlaceholderValue(variables.LOGFIRE_TOKEN)) {
      results.canaryDetected.push('LOGFIRE_TOKEN');
    }
  }

  return results;
}

/**
 * Prints summary report
 */
function printReport(envResult, appConfig, credentials) {
  console.log('\n' + '='.repeat(60));
  console.log('  CONFIGURATION VALIDATION REPORT');
  console.log('='.repeat(60) + '\n');

