      const displayValue = isPlaceholderValue(value)
        ? `${colors.gray}[CANARY/PLACEHOLDER]${colors.reset}`
        : `${colors.gray}${value.substring(0, 10)}...${colors.reset}`;
      console.log(`  ${colors.gray}→${colors.reset} ${key}: ${displayValue}`);
    });
  } else {
    log('error', 'Validation failed');
    envResult.errors.forEach(err => console.log(`  ${colors.red}→${colors.reset} ${err}`));
  }

  if (envResult.warnings.length > 0) {
    envResult.warnings.forEach(warn => console.log(`  ${colors.yellow}→${colors.reset} ${warn}`));
  }

  // Application config results
  console.log(`\n${colors.blue}Application Configuration:${colors.reset}`);
  if (appConfig.required.length > 0) {
    appConfig.required.forEach(v => {
      const source = v.default ? '(default)' : '(env)';
      log('success', `${v.name}: ${v.value} ${colors.gray}${source}${colors.reset}`);
    });
  }
  if (appConfig.optional.length > 0) {
    appConfig.optional.forEach(v => {
      log('info', `${v.name}: ${v.value} ${colors.gray}(optional)${colors.reset}`);
    });
  }
  appConfig.missing.forEach(v => {
