}

/**
 * Main execution
 */
async function main() {
  console.log('\n' + '='.repeat(60));
  console.log('  SAFE CONFIGURATION VALIDATOR');
  console.log('  Validates format without testing credentials');
  console.log('='.repeat(60) + '\n');

  const envFile = process.argv[2] || '.env.test';

