  // Exit with appropriate code
  const hasErrors = !envResult.success || appConfig.formatErrors.length > 0;
  process.exit(hasErrors ? 1 : 0);
}

// Run if executed directly
if (require.main === module) {
  main().catch(error => {
    log('error', `Fatal error: ${error.message}`);
    process.exit(1);
  });
}

