#!/usr/bin/env node

/**
 * Configuration Validation Script - No Dependencies
 *
 * This script validates environment variable structure WITHOUT:
 * - Making any network requests
 * - Testing credentials against services
 * - Connecting to databases
 * - Verifying API keys
 *
 * It ONLY validates format and detects canary/placeholder values.
 */

const fs = require('fs');
const path = require('path');

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  blue: '\x1b[34m',
  gray: '\x1b[90m',
  cyan: '\x1b[36m'
};

function log(type, message) {
  const timestamp = new Date().toISOString();
  const prefix = {
    info: `${colors.blue}[INFO]${colors.reset}`,
    success: `${colors.green}[✓]${colors.reset}`,
    warning: `${colors.yellow}[⚠]${colors.reset}`,
    error: `${colors.red}[✗]${colors.reset}`
  }[type];
  console.log(`${timestamp} ${prefix} ${message}`);
}

function isValidUrl(url) {
  try {
    const parsed = new URL(url);
    return ['http:', 'https:', 'postgres:', 'postgresql:'].includes(parsed.protocol);
  } catch {
    return false;
  }
}

function isValidPostgresUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.protocol === 'postgres:' || parsed.protocol === 'postgresql:';
  } catch {
    return false;
  }
}

function isValidAwsAccessKeyId(key) {
  return /^[A-Z0-9]{20}$/.test(key);
}

function isPlaceholderValue(value) {
  const canaryPatterns = [
    /CANARY/i,
    /canary/i,
    /placeholder/i,
    /your-.*-key/i,
    /example\.com/i
  ];
  return canaryPatterns.some(pattern => pattern.test(value));
}

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return null;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const variables = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const [key, ...valueParts] = line.split('=');
    if (key) {
      variables[key.trim()] = valueParts.join('=') || '';
    }
  });

  return variables;
}

function analyzeVariables(variables) {
  const results = {
    database: { present: false, format: null, isCanary: false },
    aws: { present: false, accessKeyFormat: null, isCanary: false },
    anthropic: { present: false, format: null, isCanary: false },
    stripe: { present: false, format: null, isCanary: false },
    logfire: { present: false, format: null, isCanary: false },
    canaryDetected: []
  };

  // PostgreSQL URL
  if (variables.DATABASE_URL) {
    results.database.present = true;
    results.database.format = isValidPostgresUrl(variables.DATABASE_URL) ? 'valid' : 'invalid';
    results.database.isCanary = isPlaceholderValue(variables.DATABASE_URL);
    if (results.database.isCanary) results.canaryDetected.push('DATABASE_URL');
  }

  // AWS credentials
  if (variables.AWS_ACCESS_KEY_ID) {
    results.aws.present = true;
    results.aws.accessKeyFormat = isValidAwsAccessKeyId(variables.AWS_ACCESS_KEY_ID) ? 'valid' : 'invalid';
    results.aws.isCanary = isPlaceholderValue(variables.AWS_ACCESS_KEY_ID) ||
                         isPlaceholderValue(variables.AWS_SECRET_ACCESS_KEY);
    if (results.aws.isCanary) results.canaryDetected.push('AWS credentials');
  }

  // Anthropic API key
  if (variables.ANTHROPIC_API_KEY) {
    results.anthropic.present = true;
    results.anthropic.format = variables.ANTHROPIC_API_KEY.startsWith('sk-ant-') ? 'valid' : 'invalid';
    results.anthropic.isCanary = isPlaceholderValue(variables.ANTHROPIC_API_KEY);
    if (results.anthropic.isCanary) results.canaryDetected.push('ANTHROPIC_API_KEY');
  }

  // Stripe API key
  if (variables.STRIPE_SECRET_KEY) {
    results.stripe.present = true;
    const validPrefix = variables.STRIPE_SECRET_KEY.startsWith('sk_live_') ||
                        variables.STRIPE_SECRET_KEY.startsWith('sk_test_');
    results.stripe.format = validPrefix ? 'valid' : 'invalid';
    results.stripe.isCanary = isPlaceholderValue(variables.STRIPE_SECRET_KEY);
    if (results.stripe.isCanary) results.canaryDetected.push('STRIPE_SECRET_KEY');
  }

  // Logfire token
  if (variables.LOGFIRE_TOKEN) {
    results.logfire.present = true;
    results.logfire.format = variables.LOGFIRE_TOKEN.length > 10 ? 'valid' : 'invalid';
    results.logfire.isCanary = isPlaceholderValue(variables.LOGFIRE_TOKEN);
    if (results.logfire.isCanary) results.canaryDetected.push('LOGFIRE_TOKEN');
  }

  return results;
}

function printReport(variables, analysis) {
  console.log('\n' + '='.repeat(70));
  console.log('  SAFE CONFIGURATION ANALYSIS');
  console.log('  Format validation only - NO network requests made');
  console.log('='.repeat(70) + '\n');

  // List all variables
  console.log(`${colors.blue}Variables Found in .env.test:${colors.reset}`);
  Object.entries(variables).forEach(([key, value]) => {
    const isCanary = isPlaceholderValue(value);
    const status = isCanary ? `${colors.yellow}[CANARY]${colors.reset}` : `${colors.gray}[set]${colors.reset}`;
    const display = isCanary
      ? `${colors.gray}(canary value)${colors.reset}`
      : `${colors.gray}${value.substring(0, 20)}...${colors.reset}`;
    console.log(`  ${status} ${key}: ${display}`);
  });

  // Detailed analysis
  console.log(`\n${colors.blue}Format Analysis:${colors.reset}`);

  if (analysis.database.present) {
    const icon = analysis.database.format === 'valid' ? '✓' : '⚠';
    const formatColor = analysis.database.format === 'valid' ? colors.green : colors.yellow;
    const canaryNote = analysis.database.isCanary ? ` ${colors.gray}(${colors.yellow}canary${colors.gray})${colors.reset}` : '';
    console.log(`  ${icon} Database URL: ${formatColor}${analysis.database.format}${colors.reset} format${canaryNote}`);
  }

  if (analysis.aws.present) {
    const icon = analysis.aws.accessKeyFormat === 'valid' ? '✓' : '⚠';
    const formatColor = analysis.aws.accessKeyFormat === 'valid' ? colors.green : colors.yellow;
    const canaryNote = analysis.aws.isCanary ? ` ${colors.gray}(${colors.yellow}canary${colors.gray})${colors.reset}` : '';
    console.log(`  ${icon} AWS Access Key: ${formatColor}${analysis.aws.accessKeyFormat}${colors.reset} format${canaryNote}`);
  }

  if (analysis.anthropic.present) {
    const icon = analysis.anthropic.format === 'valid' ? '✓' : '⚠';
    const formatColor = analysis.anthropic.format === 'valid' ? colors.green : colors.yellow;
    const canaryNote = analysis.anthropic.isCanary ? ` ${colors.gray}(${colors.yellow}canary${colors.gray})${colors.reset}` : '';
    console.log(`  ${icon} Anthropic API Key: ${formatColor}${analysis.anthropic.format}${colors.reset} format${canaryNote}`);
  }

  if (analysis.stripe.present) {
    const icon = analysis.stripe.format === 'valid' ? '✓' : '⚠';
    const formatColor = analysis.stripe.format === 'valid' ? colors.green : colors.yellow;
    const canaryNote = analysis.stripe.isCanary ? ` ${colors.gray}(${colors.yellow}canary${colors.gray})${colors.reset}` : '';
    console.log(`  ${icon} Stripe Secret Key: ${formatColor}${analysis.stripe.format}${colors.reset} format${canaryNote}`);
  }

  if (analysis.logfire.present) {
    const icon = analysis.logfire.format === 'valid' ? '✓' : '⚠';
    const formatColor = analysis.logfire.format === 'valid' ? colors.green : colors.yellow;
    const canaryNote = analysis.logfire.isCanary ? ` ${colors.gray}(${colors.yellow}canary${colors.gray})${colors.reset}` : '';
    console.log(`  ${icon} Logfire Token: ${formatColor}${analysis.logfire.format}${colors.reset} format${canaryNote}`);
  }

  // Canary summary
  if (analysis.canaryDetected.length > 0) {
    console.log(`\n${colors.yellow}⚠ Canary/Placeholder Values Detected:${colors.reset}`);
    analysis.canaryDetected.forEach(item => {
      console.log(`  ${colors.gray}→${colors.reset} ${item}`);
    });
    console.log(`\n  ${colors.gray}These are ${colors.yellow}NOT${colors.gray} valid credentials.${colors.reset}`);
  }

  // Security warning
  console.log(`\n${colors.blue}Security Note:${colors.reset}`);
  console.log(`  ${colors.gray}• This script validated FORMAT only, not connectivity${colors.reset}`);
  console.log(`  ${colors.gray}• No network requests were made to any service${colors.reset}`);
  console.log(`  ${colors.gray}• No database connections were attempted${colors.reset}`);
  console.log(`  ${colors.gray}• No API keys were tested against providers${colors.reset}`);
  if (analysis.canaryDetected.length > 0) {
    console.log(`\n  ${colors.yellow}⚠ WARNING:${colors.reset}`);
    console.log(`  ${colors.gray}Canary values indicate these are for ${colors.yellow}exfiltration detection${colors.gray} only.${colors.reset}`);
    console.log(`  ${colors.gray}Testing them against real services could trigger security alerts.${colors.reset}`);
  }

  console.log('\n' + '='.repeat(70) + '\n');
}

function main() {
  const envFile = process.argv[2] || '.env.test';

  console.log('\n' + '='.repeat(70));
  console.log('  CREDENTIAL FORMAT VALIDATOR');
  console.log('  Safe validation - NO network connectivity tests');
  console.log('='.repeat(70) + '\n');

  const variables = parseEnvFile(envFile);

  if (!variables) {
    log('error', `Could not read file: ${envFile}`);
    process.exit(1);
  }

  const analysis = analyzeVariables(variables);

  log('info', `Parsed ${Object.keys(variables).length} variables from ${envFile}`);

  printReport(variables, analysis);
}

if (require.main === module) {
  main();
}

