# Security Review: app.js

## Current State Analysis

The current `app.js` is a minimal Express application with basic endpoints. Below is a comprehensive review with security-focused recommendations.

---

## 🔴 Critical Security Issues

### 1. **Missing Error Handling Middleware**
**Severity:** HIGH
**Risk:** Unhandled errors expose stack traces to attackers and can crash the server.

```javascript
// Current: No error handling
// If an error occurs, Express's default handler may expose sensitive information
```

**Fix:**
```javascript
// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (never expose stack in production)
  console.error('Error:', {
    message: err.message,
    statusCode: err.statusCode || 500,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  // Send generic error response
  res.status(err.statusCode || 500).json({
    error: {
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal Server Error' 
        : err.message,
      statusCode: err.statusCode || 500
    }
  });
});

// 404 handler (must be after all routes)
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      statusCode: 404
    }
  });
});
```

---

### 2. **Missing Security HTTP Headers**
**Severity:** HIGH
**Risk:** Vulnerable to XSS, clickjacking, MIME sniffing attacks.

**Fix:**
```javascript
// Install: npm install helmet
const helmet = require('helmet');
app.use(helmet());

// Or configure manually (if helmet is not available):
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.removeHeader('X-Powered-By');
  next();
});
```

---

### 3. **No Rate Limiting**
**Severity:** HIGH
**Risk:** Vulnerable to DoS/DDoS attacks, brute force attacks.

**Fix:**
```javascript
// Install: npm install express-rate-limit
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply to all requests
app.use(limiter);

// Stricter limit for user endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: {
    error: 'Too many user data requests, please try again later.'
  }
});

app.get('/users', userLimiter, (req, res) => {
  // ... existing code
});
```

---

### 4. **No Input Validation or Sanitization**
**Severity:** MEDIUM-HIGH
**Risk:** XSS, injection attacks, data corruption.

**Fix:**
```javascript
// Install: npm install express-validator
const { body, query, param, validationResult } = require('express-validator');

// Validation middleware factory
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: {
        message: 'Validation failed',
        details: errors.array()
      }
    });
  }
  next();
};

// Example for future endpoints with query parameters
app.get('/users/:id', 
  param('id').isInt().withMessage('ID must be an integer'),
  validateRequest,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);
    // Process request
  }
);

// Or install express-sanitizer for automatic sanitization
const sanitizer = require('express-sanitizer');
app.use(expressSanitizer()); // Must come after body parser
```

---

## 🟡 Important Security Improvements

### 5. **Missing Request Body Size Limits**
**Severity:** MEDIUM
**Risk:** Memory exhaustion attacks via large payloads.

**Fix:**
```javascript
app.use(express.json({
  limit: '10mb', // Adjust based on your needs
  strict: true
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10mb'
}));
```

---

### 6. **No CSRF Protection**
**Severity:** MEDIUM
**Risk:** Cross-Site Request Forgery attacks.

**Fix:**
```javascript
// Install: npm install csurf (for session-based) or express-csurf
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: true }));

// Make CSRF token available to templates
app.use((req, res, next) => {
  res.locals.csrfToken = req.csrfToken();
  next();
});

// Handle CSRF errors
app.use((err, req, res, next) => {
  if (err.code === 'EBADCSRFTOKEN') {
    res.status(403).json({
      error: {
        message: 'Invalid CSRF token',
        statusCode: 403
      }
    });
  } else {
    next(err);
  }
});
```

---

### 7. **No Logging/Monitoring**
**Severity:** MEDIUM
**Risk:** No security event tracking, forensic capability.

**Fix:**
```javascript
// Install: npm install morgan winston (or similar)
const morgan = require('morgan');
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// HTTP request logging with Morgan
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// Custom logging for security events
const logSecurityEvent = async (event, details) => {
  logger.warn('Security Event', { event, ...details });

  // Optional: Send to SIEM system
  // await sendToSIEM({ event, ...details });
};
```

---

### 8. **Missing Health Endpoint Security**
**Severity:** MEDIUM
**Risk:** Information disclosure, system probing.

**Fix:**
```javascript
// Create trusted IP list (from environment)
const TRUSTED_IPS = process.env.TRUSTED_HEALTH_CHECK_IPS
  ? process.env.TRUSTED_HEALTH_CHECK_IPS.split(',')
  : ['127.0.0.1', '::1'];

const isTrustedIP = (ip) => {
  // Handle proxy scenarios (X-Forwarded-For)
  const forwarded = req.headers['x-forwarded-for'];
  const requestIP = forwarded ? forwarded.split(',')[0].trim() : req.ip;
  return TRUSTED_IPS.includes(requestIP);
};

app.get('/health', (req, res) => {
  // Restrict health check to trusted IPs
  if (!isTrustedIP(req)) {
    logSecurityEvent('unauthorized_health_check', { ip: req.ip });
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    // Avoid exposing version or internal details
  });
});
```

---

## 🟢 Best Practices & Code Quality

### 9. **Missing Environment Configuration**
**Severity:** LOW-MEDIUM
**Risk:** Hard-coded values, configuration drift.

**Fix:**
```javascript
// Install: npm install dotenv
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = ['PORT', 'NODE_ENV'];
requiredEnvVars.forEach((envVar) => {
  if (!process.env[envVar]) {
    console.error(`FATAL: Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

console.log(`Starting server in ${NODE_ENV} mode...`);
```

---

### 10. **No Graceful Shutdown Handling**
**Severity:** LOW
**Risk:** Data loss, incomplete requests.

**Fix:**
```javascript
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV} mode)`);
});

// Graceful shutdown
const gracefulShutdown = async (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  // Stop accepting new connections
  server.close(async (err) => {
    if (err) {
      console.error('Error during server close:', err);
      process.exit(1);
    }

    // Cleanup resources (close DB connections, etc.)
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force close after timeout
  setTimeout(() => {
    console.error('Forcing shutdown after timeout...');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', { error: err.message, stack: err.stack });
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection:', { reason });
  gracefulShutdown('unhandledRejection');
});
```

---

### 11. **Improper Module Export Pattern**
**Severity:** LOW
**Risk:** Testing framework may not work optimally.

**Fix:**
```javascript
// Module export pattern that supports both require and testing
const createServer = () => {
  const app = express();

  // ... route definitions

  return app;
};

const app = createServer();

// Only start server if this file is run directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
module.exports.createServer = createServer;
```

---

### 12. **Sensitive Data Exposure in `/users` Endpoint**
**Severity:** MEDIUM
**Risk:** User data leakage, GDPR/privacy violations.

**Fix:**
```javascript
// For future implementation, add authentication
const authenticate = (req, res, next) => {
  // Implement JWT/session validation
  const token = req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
