    });
  }

  // Verify token
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({
      error: { message: 'Invalid token', statusCode: 401 }
    });
  }
};

app.get('/users', authenticate, (req, res) => {
  // Only return necessary fields
  const users = getUserList().map(({ id, name }) => ({ id, name }));
  res.json(users);
});

// Or add field filtering via query params
app.get('/users', 
  query('fields').optional().isString(),
  validateRequest,
  (req, res) => {
    const { fields } = req.query;
    const allowedFields = ['id', 'name']; // Never return email by default
    const requestedFields = fields ? fields.split(',') : allowedFields;

    const users = getUserList().map(user => 
      Object.fromEntries(
        requestedFields
          .filter(f => allowedFields.includes(f))
          .map(field => [field, user[field]])
      )
    );

    res.json(users);
  }
