// Improved application with security best practices
// Error handling, input validation, and security middleware

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// Configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.set('env', NODE_ENV);

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Trust proxy if behind load balancer/reverse proxy
app.set('trust proxy', 1);

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});
app.use(limiter);

// Stricter rate limiting for API endpoints
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 50,
  message: { error: 'Too many API requests, please try again later.' }
});

// Body parsing with limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to check validation results
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Sanitization helpers
const sanitizeString = (value) => {
  if (typeof value !== 'string') return value;
  return value.trim().replace(/[<>]/g, '');
};

// ============================================================================
// ERROR HANDLING
// ============================================================================

// Custom error class
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Sanitize error messages for production
  const message = (err.isOperational || NODE_ENV !== 'production') 
    ? err.message 
    : 'Internal Server Error';

  res.status(statusCode).json({
    error: message,
    ...(NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// 404 handler (must be after all routes)
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  } catch (error) {
    next(new AppError('Health check failed', 503));
  }
});

// Users endpoint with validation
app.get('/users', 
  apiLimiter,
  [
    query('id').optional()
      .isInt({ min: 1, max: 999999999 })
      .withMessage('ID must be a positive integer'),
    query('email').optional()
      .isEmail()
      .normalizeEmail()
      .withMessage('Email must be valid'),
    query('name').optional()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters'),
    query('limit').optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('page').optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer'),
    query('sort').optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Invalid sort field')
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    let filteredUsers = [...users];

    // Filter by ID
    if (req.query.id) {
      const userId = parseInt(req.query.id);
      filteredUsers = filteredUsers.filter(user => user.id === userId);
    }

    // Filter by email (case-insensitive)
    if (req.query.email) {
      const email = req.query.email.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.email.toLowerCase() === email
      );
    }

    // Filter by name (case-insensitive partial match)
    if (req.query.name) {
      const name = sanitizeString(req.query.name).toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(name)
      );
    }

    // Sort
    if (req.query.sort) {
      filteredUsers.sort((a, b) => 
        a[req.query.sort] > b[req.query.sort] ? 1 : -1
      );
    }

    // Apply pagination
    const limit = parseInt(req.query.limit) || filteredUsers.length;
    const page = parseInt(req.query.page) || 1;
    const startIndex = (page - 1) * limit;

    const paginatedUsers = filteredUsers.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        page,
        limit,
        totalPages: Math.ceil(filteredUsers.length / limit),
        hasMore: startIndex + limit < filteredUsers.length
      }
    });
  })
);

// User by ID endpoint with param validation
app.get('/users/:id',
  apiLimiter,
  [
    param('id')
      .isInt({ min: 1, max: 999999999 })
      .withMessage('User ID must be a positive integer')
  ],
  validateRequest,
  asyncHandler(async (req, res, next) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const userId = parseInt(req.params.id);
    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json({ data: user });
  })
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
  });

  // Graceful shutdown
  const shutdown = (signal) => {
    console.log(`${signal} received, shutting down gracefully...`);
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    shutdown('UNCAUGHT_EXCEPTION');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    shutdown('UNHANDLED_REJECTION');
  });
}

module.exports = { app, AppError };

