const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

// Use Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many requests to this endpoint, please try again later.',
  },
});

app.use(limiter);

// Body parser with security constraints
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true,  // Only accept objects and arrays
}));

app.use(express.urlencoded({
  extended: false,
  limit: '10kb',
}));

// ============================================================
// VALIDATION MIDDLEWARE
// ============================================================

/**
 * Middleware to check validation results
 * Returns 400 with detailed errors if validation fails
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', {
      path: req.path,
      method: req.method,
      ip: req.ip,
      errors: errors.array(),
      timestamp: new Date().toISOString(),
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Sanitize user data before sending in response
 * Remove or escape potentially sensitive fields
 */
const sanitizeResponse = (data) => {
  if (typeof data === 'string') {
    // Basic HTML entity encoding
    return data
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeResponse);
  }
  if (data && typeof data === 'object') {
    const sanitized = {};
    for (const [key, value] of Object.entries(data)) {
      // Skip internal/hidden fields
      if (key.startsWith('_') || key === 'password' || key === 'token') {
        continue;
      }
      sanitized[key] = sanitizeResponse(value);
    }
    return sanitized;
  }
  return data;
};

// ============================================================
// LOGGING MIDDLEWARE
// ============================================================

app.use((req, res, next) => {
  const start = Date.now();

  // Log request (in production, use a proper logging library)
  console.info('Incoming request:', {
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date().toISOString(),
  });

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.info('Request completed:', {
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      timestamp: new Date().toISOString(),
    });

    // Warn on error responses
    if (res.statusCode >= 400) {
      console.warn('Client error response:', {
        method: req.method,
        path: req.path,
        statusCode: res.statusCode,
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
    }
  });

  next();
});

// ============================================================
// ERROR HANDLING
// ============================================================

/**
 * 404 Not Found Handler - Must be before error handler
 */
app.use((req, res) => {
  console.warn('404 Not Found:', {
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    path: req.path,
  });
});

/**
 * Global Error Handler
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log error details (excluding sensitive data in production)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send error response (don't expose internal details in production)
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack }),
  });
});

/**
 * Handle uncaught exceptions (prevent server crash)
 */
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
  });
  // In production, you might want to exit gracefully
  if (process.env.NODE_ENV !== 'development') {
    process.exit(1);
  }
});

/**
 * Handle unhandled promise rejections
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', {
    reason,
    promise,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Handle SIGTERM for graceful shutdown
 */
process.on('SIGTERM', () => {
  console.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

/**
 * Handle SIGINT for graceful shutdown
 */
process.on('SIGINT', () => {
  console.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// ============================================================
// ROUTES
// ============================================================

/**
 * Health check endpoint
 * GET /health
 */
app.get(
  '/health',
  [
    // Optional: validate query parameters if needed
    query('verbose')
      .optional()
      .isIn(['true', 'false', '1', '0'])
      .withMessage('verbose must be a boolean value'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
      };

      // Add verbose info if requested and authorized
      if (req.query.verbose === 'true' || req.query.verbose === '1') {
        response.uptime = process.uptime();
        response.memory = process.memoryUsage();
        response.version = process.version;
      }

      res.json(sanitizeResponse(response));
    } catch (err) {
      // Rethrow for global error handler to process
      throw err;
    }
  }
);

/**
 * Get users endpoint
 * GET /users
 */
app.get(
  '/users',
  [
    // Validate query parameters
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('limit must be an integer between 1 and 100'),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('offset must be a non-negative integer'),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('sort must be one of: id, name, email'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('order must be asc or desc'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filtering based on query params
      let result = [...users];

      const { limit = 10, offset = 0, sort = 'id', order = 'asc' } = req.query;

      // Apply sorting
      result.sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];
        const comparison = aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
        return order === 'asc' ? comparison : -comparison;
      });

      // Apply pagination
      result = result.slice(offset, offset + parseInt(limit, 10));

      res.json({
        data: sanitizeResponse(result),
        meta: {
          total: users.length,
          limit: parseInt(limit, 10),
          offset: parseInt(offset, 10),
        },
      });
    } catch (err) {
      // Rethrow for global error handler
      throw err;
    }
  }
);

/**
 * Get user by ID endpoint
 * GET /users/:id
 */
app.get(
  '/users/:id',
  [
    // Validate route parameter
    param('id')
      .isInt({ min: 1 })
      .withMessage('id must be a positive integer'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const userId = parseInt(req.params.id, 10);
      const user = users.find(u => u.id === userId);

      if (!user) {
        // Log not found event
        console.warn('User not found:', {
          userId,
          ip: req.ip,
          timestamp: new Date().toISOString(),
        });

        return res.status(404).json({
          error: 'Not Found',
          message: `User with id ${userId} does not exist`,
        });
      }

      res.json({ data: sanitizeResponse(user) });
    } catch (err) {
      throw err;
    }
  }
);

/**
 * Create user endpoint (example with body validation)
 * POST /users
 */
app.post(
  '/users',
  strictLimiter, // Stricter rate limit for mutations
  [
