# Quick Reference: Security Patterns for Express.js

## Essential Middleware Setup

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validationResult } = require('express-validator');

const app = express();

// 1. Security Headers
app.use(helmet());

// 2. Rate Limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
}));

// 3. Body Parser with Limits
app.use(express.json({ limit: '10kb' }));

// 4. Validation Helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};
```

---

## Common Validations

```javascript
const { body, query, param } = require('express-validator');

// Integer with bounds
query('limit').isInt({ min: 1, max: 100 });

// Email
body('email').isEmail().normalizeEmail();

// String with length
body('name').trim().isLength({ min: 1, max: 100 });

// Enum/Whitelist
query('sort').isIn(['id', 'name', 'email']);

// Regex
body('username').matches(/^[a-zA-Z0-9_]+$/);

// Optional field
query('page').optional().isInt({ min: 1 });

// Use in route
app.get('/endpoint', [
  query('param1').isInt(),
], validate, handler);
```

---

## Error Handler Template

```javascript
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  console.error(err); // Log to your logging service

  res.status(err.statusCode || 500).json({
    error: err.name || 'Internal Server Error',
    message: isDev ? err.message : 'An error occurred',
    ...(isDev && { stack: err.stack }),
  });
});
```

---

## Output Sanitization Helper

```javascript
function sanitize(data) {
  if (typeof data === 'string') {
    return data
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
  if (Array.isArray(data)) return data.map(sanitize);
  if (data && typeof data === 'object') {
    const clean = {};
    for (const [k, v] of Object.entries(data)) {
      if (k.startsWith('_') || k === 'password') continue;
      clean[k] = sanitize(v);
    }
    return clean;
  }
  return data;
}

res.json(sanitizeResponse(data));
```

---

## Process Error Handlers

```javascript
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
});

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);
```

---

## Route Template with Security

```javascript
app.get('/resource/:id', [
  // 1. Validate path parameter
  param('id').isInt({ min: 1 }),
  // 2. Validate query parameters
  query('fields').optional().matches(/^[a-z,]+$/),
], validate, async (req, res) => {
  try {
    // 3. Get validated data
    const id = parseInt(req.params.id);

    // 4. Fetch data (with prepared statements for DB)
