    regex: /^postgres:\/\/[^\s:@]+:[^\s@]+@[^\s:]+:\d+\/[^\s]+$/,
    example: "postgres://user:pass@host:5432/dbname"
  },
  AWS_ACCESS_KEY_ID: {
    regex: /^AKIA[A-Z0-9]{16}$/,
    example: "AKIA" + 16 chars alphanumeric
  },
  AWS_SECRET_ACCESS_KEY: {
    regex: /^[A-Za-z0-9+/=]{40}$/,
    example: 40 characters of base64
  },
  ANTHROPIC_API_KEY: {
    regex: /^sk-ant-[a-z0-9-]+$/,
    example: "sk-ant-" + alphanumeric
  },
  STRIPE_SECRET_KEY: {
    regex: /^sk_(live|test)_[a-zA-Z0-9]+$/,
    example: "sk_live_" or "sk_test_"
  },
  LOGFIRE_TOKEN: {
    regex: /^[a-zA-Z0-9-]+$/,
    example: alphanumeric and hyphens
  }
};

function validateFormat(name, value) {
  const config = validations[name];
  if (!config) return { valid: true, note: "No validation rule" };

  const isValid = config.regex.test(value);
  return {
    valid: isValid,
    example: config.example,
    note: isValid ? "Format matches expected pattern" : "Format does not match"
  };
}

console.log('=== Credential Format Validation ===\n');
console.log('Note: This validates ONLY string format.');
console.log('No network calls or API checks are performed.\n');

for (const [key, value] of Object.entries(validations)) {
  const envValue = process.env[key];
  if (!envValue) {
    console.log(`❌ ${key}: NOT SET`);
  } else {
    const result = validateFormat(key, envValue);
    console.log(`${result.valid ? '✓' : '✗'} ${key}`);
    console.log(`  Format: ${result.note}`);
    if (!result.valid) {
      console.log(`  Expected format: ${result.example}`);
    }
    console.log('');
  }
}
```

This validates **format only** without making any external connections.

