const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult, param } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Request body size limit to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// RATE LIMITING
// ============================================================================

// General rate limiter for all endpoints
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter limiter for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
});

app.use(generalLimiter);

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

// Middleware to check validation results
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array(),
    });
  }
  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler - must be before other error handlers
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'development'
    ? err.message
    : 'An internal server error occurred';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================================================
// SANITIZATION HELPERS
// ============================================================================

/**
 * Sanitize user ID to prevent SQL injection/NoSQL injection
 * @param {*} id - The ID to validate
 * @returns {number|null} - Sanitized ID or null if invalid
 */
const sanitizeUserId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0 || numId > Number.MAX_SAFE_INTEGER) {
    return null;
  }
  return numId;
};

/**
 * Sanitize email address
 * @param {string} email - Email to validate
 * @returns {string|null} - Sanitized email or null if invalid
 */
const sanitizeEmail = (email) => {
  if (typeof email !== 'string') return null;
  const trimmed = email.trim().toLowerCase();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(trimmed) ? trimmed : null;
};

/**
 * Sanitize string input (XSS prevention)
 * @param {string} str - String to sanitize
 * @returns {string} - Sanitized string
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return '';
  return str.trim().replace(/[<>]/g, '');
};

// ============================================================================
// MOCK DATA (In a real app, replace with database access)
// ============================================================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================================================
// ROUTES
// ============================================================================

/**
 * @route   GET /health
 * @desc    Health check endpoint
 * @access  Public
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (err) {
    next(err);
  }
});

/**
 * @route   GET /users
 * @desc    Get all users with optional filtering
 * @access  Public (apply auth in production)
 * @query   limit - Maximum number of users to return (1-100)
 */
app.get(
  '/users',
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('email')
      .optional()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email format'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { limit, email } = req.query;
      let filteredUsers = users;

      // Filter by email if provided
      if (email) {
        const sanitizedEmail = sanitizeEmail(email);
        if (!sanitizedEmail) {
          return res.status(400).json({
            error: 'Invalid email parameter',
          });
        }
        filteredUsers = users.filter(u => u.email === sanitizedEmail);
      }

      // Apply limit
      if (limit) {
        filteredUsers = filteredUsers.slice(0, limit);
      }

      res.json({
        count: filteredUsers.length,
        data: filteredUsers,
      });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * @route   GET /users/:id
 * @desc    Get a specific user by ID
 * @access  Public (apply auth in production)
 */
app.get(
  '/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { id } = req.params;

      const sanitizedId = sanitizeUserId(id);
      if (sanitizedId === null) {
        return res.status(400).json({
          error: 'Invalid user ID',
        });
      }

      const user = users.find(u => u.id === sanitizedId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          id: sanitizedId,
        });
      }

      res.json(user);
    } catch (err) {
      next(err);
    }
  }
);

/**
 * @route   POST /users
 * @desc    Create a new user
 * @access  Public (apply auth in production)
 */
app.post(
  '/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email format'),
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email } = req.body;

      // Check for duplicates
      const emailExists = users.some(u => u.email === email);
      if (emailExists) {
        return res.status(409).json({
          error: 'User with this email already exists',
        });
      }

      const newUser = {
        id: users.length + 1,
        name: sanitizeString(name),
        email: sanitizeEmail(email),
      };

      users.push(newUser);

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (err) {
      next(err);
    }
  }
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  const PORT = process.env.PORT || 3000;

  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Graceful shutdown
  const shutdown = (signal) => {
    console.log(`\n${signal} received, shutting down gracefully...`);
    server.close(() => {
      console.log('Server closed');
      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

module.exports = app;

